// GENERADO por backend/herramientas/generar_aprende.py a partir de backend/retos/conceptos/javascript.py. No lo edites a mano: cambia los conceptos y vuelve a generarlo.
// m = etapa · t = título · x = qué es · u = para qué sirve · p = puntos clave · c = código · h = qué hace · r = ahora tú · e = error común
export default [
  {"m": "Qué es JavaScript", "t": "Qué es JavaScript", "x": "Lenguaje de programación que da vida a las páginas web.\n\nHTML pone la estructura y CSS el estilo; JavaScript hace que la página reaccione: abrir menús, validar formularios, mostrar mensajes o actualizar datos sin recargar. Es el único lenguaje que todos los navegadores entienden de forma nativa.", "u": "Añadir comportamiento e interacción a una página.\n\nQuieres que un botón de tu página muestre un mensaje al pulsarlo.", "p": ["JavaScript añade comportamiento a las páginas web.", "Todos los navegadores entienden JavaScript.", "JavaScript es un lenguaje de programación, a diferencia de HTML."], "c": "// JavaScript puede ejecutar acciones\nconsole.log(\"¡Hola desde JavaScript!\");\nconsole.log(2 + 3);", "h": "Muestra un saludo y una suma en la consola.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El lenguaje que da comportamiento a las páginas web es ___. (10 letras)", "e": "Creer que JavaScript solo sirve para validar formularios."},
  {"m": "Qué es JavaScript", "t": "Para qué sirve JavaScript", "x": "Lista de usos reales del lenguaje en la web y fuera de ella.\n\nCon JavaScript se hacen páginas interactivas, aplicaciones web como Gmail, juegos en el navegador, servidores con Node.js, aplicaciones móviles y de escritorio, e incluso robots. Es uno de los lenguajes más usados del mundo.", "u": "Saber qué se puede construir aprendiendo JavaScript.\n\nTe preguntas si lo que aprendas con este lenguaje te permitirá hacer apps, juegos y servidores.", "p": ["JavaScript se usa en el navegador y también en servidores.", "Con JavaScript se pueden crear juegos y aplicaciones.", "Es uno de los lenguajes más usados del mundo."], "c": "// Ejemplos de lo que se puede construir\nconst usos = [\"páginas interactivas\", \"juegos\", \"servidores\", \"apps móviles\"];\nconsole.log(\"Con JavaScript puedes hacer:\");\nfor (const uso of usos) console.log(\"- \" + uso);", "h": "Lista cuatro cosas que se pueden construir con el lenguaje.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Con JavaScript se pueden crear páginas, juegos y ___ web. (una palabra: aplicaciones)", "e": "Pensar que JavaScript solo sirve para animaciones."},
  {"m": "Qué es JavaScript", "t": "JavaScript y Java", "x": "Dos lenguajes distintos con nombres parecidos.\n\nNo tienen relación. JavaScript se llamó así por una estrategia de marketing en los años 90, cuando Java era muy popular. Se diferencian en cómo se escriben, dónde se ejecutan y para qué se usan. Si buscas ayuda, escribe siempre «JavaScript» completo.", "u": "Evitar confusiones al buscar información.\n\nAlguien te dice que JavaScript es una versión simplificada de Java.", "p": ["JavaScript y Java son lenguajes distintos.", "El nombre parecido fue una decisión de marketing.", "Al buscar ayuda hay que escribir JavaScript completo."], "c": "// JavaScript (este lenguaje)\nconsole.log(\"Soy JavaScript\");\n// Java es otro lenguaje con otra sintaxis:\n// System.out.println(\"Soy Java\");", "h": "Muestra un mensaje en JavaScript y deja comentada la forma de hacerlo en Java.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: JavaScript y ___ son lenguajes distintos. (4 letras)", "e": "Creer que aprender Java es lo mismo que aprender JavaScript."},
  {"m": "Qué es JavaScript", "t": "ECMAScript", "x": "Estándar que define cómo debe funcionar JavaScript.\n\nECMAScript (ES) es la especificación oficial y JavaScript es su implementación más conocida. Cada año sale una versión: ES6 (2015) trajo let, const y las funciones flecha, y por eso se habla de «JavaScript moderno». Los navegadores adoptan las novedades poco a poco.", "u": "Garantizar que el lenguaje funcione igual en todos los navegadores.\n\nQuieres nombrar al estándar oficial que define las reglas de JavaScript.", "p": ["ECMAScript es el estándar que define JavaScript.", "ES6 (2015) introdujo let, const y las funciones flecha.", "Cada año aparece una nueva versión del estándar."], "c": "// Novedades de ES6 (2015) que usaremos siempre\nconst saludo = \"Hola\";                  // const y let vienen de ES6\nconst doble = (n) => n * 2;             // función flecha, también de ES6\nconsole.log(saludo, doble(21));", "h": "Usa dos novedades de ES6: const y una función flecha.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El estándar que define JavaScript se llama ___Script. (3 letras)", "e": "Creer que ES6 y JavaScript son lenguajes distintos."},
  {"m": "Qué es JavaScript", "t": "Navegador y consola", "x": "Entorno donde se ejecuta JavaScript y se ven sus mensajes.\n\nTodos los navegadores traen un motor de JavaScript (V8 en Chrome, SpiderMonkey en Firefox). Con F12 abres las herramientas de desarrollo y, en la pestaña Consola, puedes escribir código al instante y ver los mensajes de console.log y los errores.", "u": "Probar código y ver errores mientras programas.\n\nQuieres escribir una línea de JavaScript y ver su resultado al instante en el navegador.", "p": ["El navegador incluye un motor que ejecuta JavaScript.", "La consola se abre con F12.", "En la consola se ven los mensajes y los errores del código."], "c": "// Pega esto en la consola del navegador (F12)\nconsole.log(\"Esto aparece en la consola\");\nconsole.error(\"Así se ve un mensaje de error\");\nconsole.warn(\"Y así una advertencia\");", "h": "Muestra un mensaje normal, un error y una advertencia en la consola.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La consola se abre con la tecla ___. (3 caracteres)", "e": "Programar sin mirar nunca los errores de la consola."},
  {"m": "Qué es JavaScript", "t": "Node.js", "x": "Entorno que ejecuta JavaScript fuera del navegador.\n\nNode.js usa el mismo motor V8 de Chrome pero sin página web: sirve para programas en la terminal, servidores y herramientas. Con él, un mismo lenguaje sirve para el cliente y el servidor. Incluye npm, el mayor repositorio de librerías.", "u": "Crear servidores, herramientas y scripts con JavaScript.\n\nQuieres ejecutar JavaScript en tu computadora sin abrir ningún navegador.", "p": ["Node.js ejecuta JavaScript fuera del navegador.", "Node.js incluye npm para instalar librerías.", "Con Node.js se pueden crear servidores."], "c": "// Guarda esto como hola.js y ejecútalo en la terminal con: node hola.js\nconsole.log(\"Hola desde Node.js\");\nconsole.log(\"Versión de JavaScript lista:\", typeof console);", "h": "Muestra mensajes ejecutados por Node.js sin navegador.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El entorno que ejecuta JavaScript fuera del navegador es ___.js. (4 letras)", "e": "Creer que JavaScript solo funciona dentro de un navegador."},
  {"m": "Qué es JavaScript", "t": "Script en HTML", "x": "Etiqueta script que incluye código JavaScript en una página.\n\nEl código se escribe entre <script> y </script>. Suele ir al final del body para que el HTML ya exista cuando se ejecute. El navegador lee la página de arriba abajo y ejecuta cada script al encontrarlo.", "u": "Ejecutar JavaScript cuando se abre la página.\n\nQuieres escribir código JavaScript dentro de tu archivo HTML.", "p": ["La etiqueta script incluye código JavaScript en una página.", "Suele colocarse al final del body.", "El navegador ejecuta el script al encontrarlo."], "c": "<h1 id=\"titulo\">Hola</h1>\n<script>\n  // este código se ejecuta al abrir la página\n  document.getElementById(\"titulo\").textContent = \"Cambiado con JavaScript\";\n</script>", "h": "Cambia el texto del título desde un script dentro del HTML.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El código JavaScript en HTML se escribe dentro de la etiqueta ___. (6 letras)", "e": "Poner el script antes del HTML que necesita y recibir errores."},
  {"m": "Qué es JavaScript", "t": "Archivo .js externo", "x": "Archivo aparte que contiene solo código JavaScript.\n\nSe guarda con extensión .js y se enlaza con <script src=\"app.js\"></script>. Mantiene el HTML limpio, permite usar el mismo código en varias páginas y el navegador lo guarda en caché. Es la forma recomendada de organizar el código.", "u": "Separar el código de la página y reutilizarlo.\n\nQuieres usar el mismo código JavaScript en cinco páginas distintas.", "p": ["Un archivo externo de JavaScript termina en .js.", "Se enlaza con script y el atributo src.", "Es la forma recomendada de organizar el código."], "c": "<!-- index.html -->\n<script src=\"js/app.js\" defer></script>\n\n// js/app.js contendría:\n// console.log(\"Archivo externo cargado\");", "h": "Enlaza un archivo JavaScript externo desde el HTML.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un archivo de JavaScript termina en ___. (3 caracteres con punto)", "e": "Olvidar la ruta correcta del archivo .js."},
  {"m": "Qué es JavaScript", "t": "Instrucciones y punto y coma", "x": "Cada orden del programa, que suele terminar con punto y coma.\n\nUn programa es una lista de instrucciones que se ejecutan de arriba abajo, una tras otra. Conviene terminar cada una con punto y coma. JavaScript puede insertarlo por ti, pero depender de eso causa errores sutiles.", "u": "Separar las órdenes que el programa ejecuta en secuencia.\n\nQuieres que dos órdenes se ejecuten una tras otra, separadas con el símbolo adecuado.", "p": ["Las instrucciones se ejecutan en orden, de arriba abajo.", "Conviene terminar cada instrucción con punto y coma.", "El orden de las instrucciones cambia el resultado."], "c": "console.log(\"Primero\");\nconsole.log(\"Segundo\");\nconsole.log(\"Tercero\");\n// El orden importa: se ejecutan de arriba abajo", "h": "Ejecuta tres instrucciones en orden, una tras otra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Cada instrucción termina convenientemente con ___. (punto y coma)", "e": "Escribir dos instrucciones en la misma línea sin separarlas."},
  {"m": "Qué es JavaScript", "t": "Comentarios en JavaScript", "x": "Notas en el código que el programa ignora.\n\nUn comentario de una línea empieza con //. Uno de varias líneas va entre /* y */. Sirven para explicar el porqué de un código, no para repetir lo evidente. También se usan para desactivar líneas mientras pruebas.", "u": "Explicar el código y desactivar líneas.\n\nQuieres dejar una nota en el código que el programa no ejecute.", "p": ["Los comentarios de una línea empiezan con //.", "Los comentarios de varias líneas van entre /* y */.", "El programa ignora los comentarios."], "c": "// Esto es un comentario de una línea\nconsole.log(\"Esto sí se ejecuta\");\n/* Un comentario\n   de varias líneas */\n// console.log(\"Esta línea está desactivada\");", "h": "Ejecuta solo una línea y deja el resto comentado o desactivado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un comentario de una línea empieza con ___. (2 caracteres)", "e": "Comentar lo obvio en lugar de explicar el porqué."},
  {"m": "Qué es JavaScript", "t": "console.log", "x": "Instrucción que muestra información en la consola.\n\nconsole.log(valor) escribe en la consola lo que le pases: textos, números, resultados de operaciones. Puedes pasarle varios valores separados por comas. Es tu mejor herramienta para depurar: «imprime» el valor para ver qué contiene.", "u": "Ver valores y comprobar qué hace el programa.\n\nQuieres ver en la consola el resultado de una operación para comprobar tu código.", "p": ["console.log muestra valores en la consola.", "Acepta varios valores separados por comas.", "Es la herramienta más usada para depurar."], "c": "console.log(\"Hola\");                 // un texto\nconsole.log(7 * 6);                  // el resultado de una operación\nconsole.log(\"Resultado:\", 7 * 6);    // varios valores a la vez", "h": "Muestra un texto, un cálculo y ambos juntos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que muestra algo en la consola es console.___. (3 letras)", "e": "Olvidar los paréntesis de console.log. Falta el paréntesis: console.log(\"Adiós\");"},
  {"m": "Qué es JavaScript", "t": "Alert y prompt", "x": "Ventanas del navegador para avisar o pedir un dato.\n\nalert(\"texto\") muestra un aviso con un botón. prompt(\"pregunta\") abre una ventana para escribir y devuelve lo escrito. Son útiles para aprender, pero en proyectos reales se prefieren elementos de la propia página, porque estas ventanas bloquean todo.", "u": "Interactuar con la persona de forma muy sencilla.\n\nQuieres preguntar el nombre al visitante con una ventana sencilla del navegador.", "p": ["alert muestra una ventana de aviso.", "prompt pide un dato y devuelve el texto escrito.", "Estas ventanas bloquean la página mientras están abiertas."], "c": "// Estas funciones solo existen en el navegador\n// alert(\"¡Bienvenida!\");\n// const nombre = prompt(\"¿Cómo te llamas?\");\n// console.log(\"Hola, \" + nombre);\nconsole.log(\"alert avisa y prompt pregunta\");", "h": "Explica cómo avisar y preguntar con ventanas del navegador.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que muestra un aviso en una ventana es ___. (5 letras)", "e": "Usar alert por todas partes en un proyecto real."},
  {"m": "Qué es JavaScript", "t": "Qué es una variable", "x": "Espacio con nombre donde se guarda un dato.\n\nImagina una caja con una etiqueta: la etiqueta es el nombre de la variable y lo que hay dentro es su valor. Puedes cambiar el contenido de la caja, y usar su nombre en lugar del valor cada vez que lo necesites. En el siguiente bloque aprenderás a crearlas.", "u": "Recordar valores para usarlos más tarde.\n\nQuieres guardar la edad de una persona para usarla en varios sitios del programa.", "p": ["Una variable guarda un dato con un nombre.", "El valor de una variable puede cambiar.", "Se usa el nombre de la variable en lugar del valor."], "c": "let edad = 20;              // guardamos 20 con el nombre «edad»\nconsole.log(edad);          // usamos el nombre\nedad = 21;                  // cambiamos el valor\nconsole.log(edad);", "h": "Guarda una edad, la muestra y la cambia.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una variable guarda un ___ con un nombre. (4 letras)", "e": "Escribir el valor en todas partes en lugar de usar una variable."},
  {"m": "Qué es JavaScript", "t": "Qué es un tipo de dato", "x": "Clase de valor que puede guardar una variable.\n\nLos textos (string), los números (number) y los verdaderos o falsos (boolean) son tipos distintos. No se comportan igual: puedes multiplicar números, pero no textos. Saber de qué tipo es un dato evita muchos errores.", "u": "Saber qué operaciones se pueden hacer con un dato.\n\nQuieres distinguir si un dato es un texto, un número o un verdadero/falso.", "p": ["Los principales tipos son texto, número y booleano.", "Cada tipo permite operaciones distintas.", "Conocer el tipo de un dato evita errores."], "c": "console.log(typeof \"Hola\");     // string\nconsole.log(typeof 42);         // number\nconsole.log(typeof true);       // boolean", "h": "Muestra el tipo de un texto, un número y un booleano.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los tres tipos básicos son string, number y ___. (7 letras)", "e": "Intentar multiplicar textos como si fueran números."},
  {"m": "Qué es JavaScript", "t": "Qué es una función", "x": "Bloque de código con nombre que se puede ejecutar cuando se quiera.\n\nUna función agrupa varias instrucciones bajo un nombre. La defines una vez y la «llamas» cuantas veces necesites. Puede recibir datos (parámetros) y devolver un resultado. Es como una receta que usas siempre que quieras.", "u": "No repetir código y organizar el programa.\n\nQuieres escribir un saludo una vez y usarlo diez veces sin copiar el código.", "p": ["Una función agrupa instrucciones bajo un nombre.", "Se define una vez y se llama muchas veces.", "Puede recibir datos y devolver un resultado."], "c": "function saludar() {\n  console.log(\"¡Hola!\");\n}\nsaludar();      // primera llamada\nsaludar();      // segunda llamada", "h": "Define un saludo una vez y lo ejecuta dos veces.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un bloque de código con nombre que se puede ejecutar varias veces es una ___. (7 letras)", "e": "Copiar y pegar el mismo código en lugar de crear una función."},
  {"m": "Qué es JavaScript", "t": "Qué es un evento", "x": "Algo que ocurre en la página y a lo que se puede responder.\n\nUn clic, pulsar una tecla, enviar un formulario, escribir en un campo o cargar la página son eventos. Con JavaScript «escuchas» un evento y ejecutas una función cuando ocurre. Es la base de toda la interactividad.", "u": "Hacer que la página reaccione a lo que hace la persona.\n\nQuieres ejecutar un código justo cuando la persona pulsa un botón.", "p": ["Un clic o una pulsación de tecla son eventos.", "Se escucha un evento y se ejecuta una función al ocurrir.", "Los eventos son la base de la interactividad."], "c": "// Los eventos solo existen en el navegador; así se escucharía un clic:\n// boton.addEventListener(\"click\", () => console.log(\"¡Clic!\"));\nconsole.log(\"Evento = algo que ocurre, y una función que responde\");", "h": "Explica cómo se escucharía un clic para ejecutar una función.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Pulsar un botón es un ___ de clic. (6 letras: evento)", "e": "Intentar leer el valor de un campo antes de que ocurra el evento."},
  {"m": "Qué es JavaScript", "t": "Qué es el DOM", "x": "Representación de la página como árbol de elementos manipulable.\n\nEl navegador convierte tu HTML en un árbol de objetos llamado DOM (Document Object Model). JavaScript puede leer ese árbol, cambiar textos y estilos, añadir o quitar elementos. El objeto document es la puerta de entrada.", "u": "Leer y cambiar el contenido de la página con código.\n\nQuieres cambiar el texto de un título de la página con código.", "p": ["El DOM es el árbol de elementos de la página.", "JavaScript puede modificar el DOM.", "El objeto document es la entrada al DOM."], "c": "<h1 id=\"t\">Título original</h1>\n<script>\n  const t = document.getElementById(\"t\");   // el DOM nos da el elemento\n  t.textContent = \"Título cambiado\";        // cambiamos su texto\n  console.log(t.textContent);\n</script>", "h": "Busca un título en el DOM y le cambia el texto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las siglas de Document Object Model son ___. (3 letras)", "e": "Confundir el DOM con el código HTML original."},
  {"m": "Qué es JavaScript", "t": "Interpretado y compilado", "x": "Dos formas de convertir el código en algo que la máquina ejecuta.\n\nUn lenguaje compilado se traduce entero antes de ejecutarse. JavaScript es interpretado (con compilación justo a tiempo): el motor lo traduce mientras corre. Por eso, muchos errores solo aparecen al ejecutar la línea que los contiene.", "u": "Entender cuándo se detecta cada error.\n\nNotas que un error en tu código solo aparece al ejecutar justo esa línea.", "p": ["JavaScript se interpreta mientras se ejecuta.", "Los lenguajes compilados se traducen antes de ejecutarse.", "Muchos errores de JavaScript aparecen solo al ejecutar la línea."], "c": "console.log(\"Esta línea se ejecuta bien\");\n// La siguiente tiene un error pero no se detecta hasta llegar a ella:\n// console.log(variableInexistente);\nconsole.log(\"Fin del programa\");", "h": "Ejecuta líneas en orden y deja comentada una que fallaría al llegar a ella.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: JavaScript se ___ mientras se ejecuta. (9 letras: interpreta)", "e": "Creer que el error se detecta antes de ejecutar el programa."},
  {"m": "Qué es JavaScript", "t": "Errores y consola", "x": "Mensajes que indican qué falló y en qué línea.\n\nUn error de sintaxis (falta un paréntesis) impide que el programa arranque. Un error en ejecución (usar una variable que no existe) lo detiene al llegar a esa línea. La consola indica el tipo de error, el mensaje y el número de línea: léelo siempre entero.", "u": "Encontrar y corregir fallos del código.\n\nTu programa se detiene y ves un mensaje rojo con una línea indicada.", "p": ["La consola indica el tipo de error y la línea.", "Los errores de sintaxis impiden que el programa arranque.", "Hay que leer el mensaje de error completo."], "c": "try {\n  console.log(noExiste);          // esta variable no existe\n} catch (error) {\n  console.log(\"Tipo:\", error.name);          // ReferenceError\n  console.log(\"Mensaje:\", error.message);    // dice qué falló\n}", "h": "Captura un error y muestra su tipo y su mensaje.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El error por usar una variable que no existe es un ___Error. (9 letras: Reference)", "e": "Ignorar el mensaje de error y cambiar código al azar."},
  {"m": "Qué es JavaScript", "t": "Cómo practicar JavaScript", "x": "Costumbre de escribir y probar código a diario.\n\nProgramar se aprende programando. Escribe cada ejemplo, cambia valores, rompe el código a propósito y arréglalo. Mini-proyectos como una calculadora o una lista de tareas enseñan más que leer teoría. Practica un poco cada día.", "u": "Aprender más rápido y fijar lo estudiado.\n\nQuieres aprender JavaScript de verdad y no solo memorizarlo.", "p": ["Programar se aprende escribiendo código.", "Los mini-proyectos enseñan mucho.", "Practicar un poco cada día es mejor que mucho de golpe."], "c": "// Reto: cambia los valores y observa el resultado\nconst nombre = \"Ana\";\nconst edad = 20;\nconsole.log(\"Me llamo \" + nombre + \" y tengo \" + edad + \" años\");\n// Ahora añade una variable «ciudad» y muéstrala", "h": "Une un nombre y una edad en una frase y deja un reto para ampliarla.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Programar se aprende ___. (10 letras: programando)", "e": "Leer teoría sin escribir nunca código."},
  {"m": "Variables, tipos y operadores", "t": "let", "x": "Palabra que declara una variable cuyo valor puede cambiar.\n\nlet crea una variable con alcance de bloque: solo existe dentro de las llaves donde se declaró. Puedes reasignarle valores, pero no declararla dos veces con el mismo nombre en el mismo bloque. Es la opción para contadores y datos que cambian.", "u": "Guardar datos que se modificarán durante el programa.\n\nQuieres un contador que empieza en 0 y aumenta durante el programa.", "p": ["let declara una variable cuyo valor puede cambiar.", "Una variable let solo existe dentro de su bloque.", "No se puede declarar dos veces el mismo let en un bloque."], "c": "let puntos = 0;            // se declara con let\nconsole.log(puntos);       // 0\npuntos = puntos + 10;      // se puede cambiar\nconsole.log(puntos);       // 10", "h": "Declara un contador y cambia su valor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para declarar una variable que cambiará usamos la palabra ___. (3 letras)", "e": "Declarar dos veces la misma variable con let. No se puede declarar otra vez puntos con let; basta con asignarle un valor nuevo."},
  {"m": "Variables, tipos y operadores", "t": "const", "x": "Palabra que declara una constante que no se reasigna.\n\nconst exige un valor al declararla y no permite reasignarlo. Es la opción por defecto en JavaScript moderno: usa const siempre y cambia a let solo si necesitas reasignar. Ojo: un array o un objeto const sí puede modificar su contenido, aunque no ser reasignado.", "u": "Guardar datos que no deben cambiar.\n\nQuieres guardar el valor de PI, que nunca debe cambiar.", "p": ["const declara una variable que no se reasigna.", "Una constante debe tener un valor al declararla.", "Un objeto declarado con const sí puede cambiar su contenido."], "c": "const PI = 3.1416;               // no se podrá reasignar\nconsole.log(PI);\ntry {\n  PI = 3;                        // intento de cambiarla\n} catch (error) {\n  console.log(error.name);       // TypeError\n}", "h": "Intenta cambiar una constante y muestra el error que produce.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para declarar un valor que no se reasigna usamos ___. (5 letras)", "e": "Usar let para todo cuando bastaba const. Una constante no puede reasignarse: habría que declarar edad con let."},
  {"m": "Variables, tipos y operadores", "t": "var", "x": "Forma antigua de declarar variables con alcance de función.\n\nAntes de 2015 solo existía var. Su alcance es la función entera (no el bloque) y permite redeclarar la variable, lo que provoca errores difíciles de ver. Se «eleva» (hoisting) al principio del alcance, con valor undefined. Hoy se prefieren let y const.", "u": "Entender código antiguo y evitar sus problemas.\n\nLees un código antiguo que declara variables con una palabra que hoy se evita.", "p": ["var tiene alcance de función, no de bloque.", "var permite declarar dos veces el mismo nombre.", "Hoy se prefieren let y const."], "c": "if (true) {\n  var a = \"visible fuera del bloque\";\n  let b = \"solo dentro del bloque\";\n}\nconsole.log(a);                      // funciona\nconsole.log(typeof b);               // undefined: b no existe aquí", "h": "Compara una variable var, visible fuera del bloque, con una let que no lo es.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La forma antigua de declarar variables es ___. (3 letras)", "e": "Usar var por costumbre y provocar variables que se filtran."},
  {"m": "Variables, tipos y operadores", "t": "Nombres de variables", "x": "Reglas y convenciones para escribir identificadores.\n\nPueden contener letras, números, _ y $, pero no empezar por número ni usar palabras reservadas como let o function. JavaScript distingue mayúsculas de minúsculas: edad y Edad son distintas. La convención es camelCase: nombreCompleto, edadMinima. Elige nombres que expliquen su contenido.", "u": "Que el código se lea y se entienda con facilidad.\n\nQuieres nombrar una variable de varias palabras con el estilo habitual de JavaScript.", "p": ["Un nombre de variable no puede empezar con un número.", "JavaScript distingue entre mayúsculas y minúsculas.", "La convención habitual es camelCase."], "c": "const nombreCompleto = \"Ana Pérez\";    // camelCase\nconst edadMinima = 18;\nlet Total = 1;\nlet total = 2;                          // distinta de Total\nconsole.log(nombreCompleto, edadMinima, Total, total);", "h": "Usa camelCase y muestra que mayúsculas y minúsculas son nombres distintos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El estilo nombreCompleto, con mayúscula en cada palabra nueva, se llama ___Case. (5 letras: camel)", "e": "Usar nombres como x1 o dato sin significado. Un nombre de variable no puede empezar con un número."},
  {"m": "Variables, tipos y operadores", "t": "Strings", "x": "Tipo de dato para guardar texto entre comillas.\n\nUn string se escribe entre comillas simples, dobles o invertidas. Cada carácter tiene una posición que empieza en 0: «Hola»[0] es «H». La propiedad length da el número de caracteres. Los strings son inmutables: sus métodos devuelven un texto nuevo.", "u": "Trabajar con nombres, frases y mensajes.\n\nQuieres guardar el nombre «Ana» como un dato de texto.", "p": ["Un string se escribe entre comillas.", "La primera posición de un texto es la 0.", "La propiedad length indica cuántos caracteres tiene."], "c": "const saludo = \"Hola, mundo\";\nconsole.log(saludo.length);      // 11 caracteres\nconsole.log(saludo[0]);          // H (la primera posición es 0)\nconsole.log(saludo.toUpperCase());   // devuelve un texto nuevo", "h": "Mide un texto, toma su primera letra y lo pasa a mayúsculas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que da el número de caracteres es ___. (6 letras)", "e": "Creer que la primera letra está en la posición 1."},
  {"m": "Variables, tipos y operadores", "t": "Numbers", "x": "Tipo de dato para guardar números enteros y decimales.\n\nEn JavaScript todos los números son del mismo tipo: number, tanto enteros (5) como decimales (3.14). Se escriben sin comillas. Los decimales usan punto, no coma. Existen valores especiales como Infinity y NaN.", "u": "Hacer cálculos matemáticos.\n\nQuieres guardar el precio 4.5 para poder hacer cálculos con él.", "p": ["JavaScript usa un único tipo number para enteros y decimales.", "Los decimales se escriben con punto.", "Los números no llevan comillas."], "c": "const entero = 42;\nconst decimal = 3.14;       // punto decimal, no coma\nconsole.log(entero + decimal);\nconsole.log(typeof entero, typeof decimal);   // ambos son number", "h": "Suma un entero y un decimal y muestra que ambos son del mismo tipo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los decimales en JavaScript se escriben con ___ decimal. (5 letras: punto)", "e": "Escribir un decimal con coma."},
  {"m": "Variables, tipos y operadores", "t": "Booleanos", "x": "Tipo de dato con solo dos valores: true o false.\n\ntrue y false se escriben sin comillas y en minúscula. Aparecen como resultado de comparaciones (5 > 3 es true) y controlan las decisiones del programa. «true» entre comillas sería un texto, no un booleano.", "u": "Tomar decisiones según una condición.\n\nQuieres guardar si un usuario ha iniciado sesión (sí o no).", "p": ["Un booleano solo puede ser true o false.", "Las comparaciones devuelven booleanos.", "true entre comillas es un texto, no un booleano."], "c": "const mayorDeEdad = 20 >= 18;      // el resultado es true\nconst premium = false;\nconsole.log(mayorDeEdad, premium);\nconsole.log(typeof mayorDeEdad);   // boolean", "h": "Obtiene un booleano de una comparación y guarda otro directamente.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los dos valores de un booleano son true y ___. (5 letras)", "e": "Escribir True con mayúscula inicial."},
  {"m": "Variables, tipos y operadores", "t": "null y undefined", "x": "Dos valores especiales que representan la ausencia de dato.\n\nundefined es lo que tiene una variable declarada pero sin valor. null es un vacío que asignas tú a propósito para indicar «aquí no hay nada». Ambos son falsy. Comprueba con === null o === undefined, o usa ?? para dar un valor por defecto.", "u": "Distinguir «no asignado» de «vacío a propósito».\n\nDeclaraste una variable pero todavía no le diste ningún valor.", "p": ["undefined significa que la variable no tiene valor asignado.", "null es un vacío asignado a propósito.", "Ambos valores se consideran falsy."], "c": "let sinValor;                  // declarada pero sin asignar\nconsole.log(sinValor);          // undefined\nconst vacio = null;             // vacío puesto a propósito\nconsole.log(vacio);             // null\nconsole.log(typeof sinValor, typeof vacio);", "h": "Compara una variable sin valor con un vacío asignado a propósito.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una variable declarada sin valor contiene ___. (9 letras)", "e": "Confundir null con undefined."},
  {"m": "Variables, tipos y operadores", "t": "typeof", "x": "Operador que devuelve el tipo de un dato.\n\ntypeof 5 da \"number\", typeof \"a\" da \"string\" y typeof true da \"boolean\". Curiosidad: typeof null da \"object\" (un error histórico del lenguaje) y typeof de una función da \"function\". Es útil para validar datos antes de usarlos.", "u": "Comprobar de qué tipo es un valor.\n\nQuieres saber de qué tipo es una variable antes de operar con ella.", "p": ["typeof devuelve el tipo de un valor como texto.", "typeof null devuelve «object» por un error histórico.", "typeof de una función devuelve «function»."], "c": "console.log(typeof 5);               // number\nconsole.log(typeof \"hola\");          // string\nconsole.log(typeof true);            // boolean\nconsole.log(typeof undefined);       // undefined\nconsole.log(typeof null);            // object (error histórico)\nconsole.log(typeof function () {});  // function", "h": "Muestra el tipo de seis valores distintos, incluido el curioso caso de null.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que devuelve el tipo de un valor es ___. (6 letras)", "e": "Olvidar que typeof null es object."},
  {"m": "Variables, tipos y operadores", "t": "Operadores aritméticos", "x": "Símbolos para sumar, restar, multiplicar, dividir y más.\n\n+ suma, - resta, * multiplica, / divide, % da el resto de una división y ** eleva a una potencia. La multiplicación y la división se evalúan antes que la suma y la resta; usa paréntesis para cambiar el orden. El resto (%) sirve, por ejemplo, para saber si un número es par.", "u": "Hacer cálculos con números.\n\nQuieres saber si un número es par comprobando el resto de dividirlo entre 2.", "p": ["El operador % devuelve el resto de una división.", "El operador ** eleva a una potencia.", "Los paréntesis cambian el orden de las operaciones."], "c": "console.log(7 + 3, 7 - 3, 7 * 3);\nconsole.log(7 / 2);          // 3.5\nconsole.log(7 % 2);          // 1 (resto)\nconsole.log(2 ** 3);         // 8\nconsole.log((2 + 3) * 4);    // 20 (los paréntesis mandan)", "h": "Muestra los operadores aritméticos y el efecto de los paréntesis.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que da el resto de una división es ___. (un carácter)", "e": "Olvidar que * y / se calculan antes que + y -."},
  {"m": "Variables, tipos y operadores", "t": "Asignación compuesta", "x": "Operadores que modifican una variable a partir de su valor actual.\n\nx += 5 equivale a x = x + 5. Existen -=, *=, /= y %=. Para sumar o restar uno hay ++ y --. Son muy comunes en bucles y contadores.", "u": "Escribir más corto operaciones como contar o acumular.\n\nQuieres sumar 10 a una variable de puntos escribiendo lo menos posible.", "p": ["x += 5 equivale a x = x + 5.", "++ aumenta una variable en uno.", "Los operadores compuestos acortan el código."], "c": "let puntos = 10;\npuntos += 5;       // 15\npuntos *= 2;       // 30\npuntos -= 10;      // 20\npuntos++;          // 21\nconsole.log(puntos);", "h": "Modifica una variable con cuatro operadores compuestos distintos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Escribe el operador que suma y asigna a la vez (2 caracteres).", "e": "Escribir =+ en lugar de +=."},
  {"m": "Variables, tipos y operadores", "t": "Igualdad estricta", "x": "Comparación con === que revisa valor y tipo.\n\n== convierte los tipos antes de comparar y da resultados extraños: 5 == \"5\" es true. === compara valor y tipo: 5 === \"5\" es false. Usa siempre === y !== salvo que sepas muy bien por qué usar ==.", "u": "Comparar sin conversiones sorpresa.\n\nQuieres comparar 5 con «5» sin que JavaScript los convierta.", "p": ["=== compara valor y tipo.", "== convierte los tipos antes de comparar.", "Se recomienda usar siempre === y !==."], "c": "console.log(5 == \"5\");      // true  (convierte el texto)\nconsole.log(5 === \"5\");     // false (distinto tipo)\nconsole.log(5 !== \"5\");     // true\nconsole.log(0 == false);    // true  (¡sorpresa!)\nconsole.log(0 === false);   // false", "h": "Compara igualdad con conversión y sin ella para ver las diferencias.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador de igualdad estricta es ___. (3 caracteres)", "e": "Usar == y sufrir conversiones inesperadas. Se usó = (asignación) en vez de === (comparación)."},
  {"m": "Variables, tipos y operadores", "t": "Operadores lógicos", "x": "Operadores que combinan valores booleanos.\n\n&& (y) es true si ambas condiciones son true. || (o) es true si al menos una lo es. ! (no) invierte el valor. Evalúan de izquierda a derecha y se detienen en cuanto conocen el resultado (cortocircuito).", "u": "Tomar decisiones con varias condiciones.\n\nQuieres comprobar que alguien es mayor de edad y además tiene entrada.", "p": ["&& exige que se cumplan las dos condiciones.", "|| exige que se cumpla al menos una.", "! invierte un valor booleano."], "c": "const edad = 20;\nconst tieneEntrada = true;\nconsole.log(edad >= 18 && tieneEntrada);   // true: se cumplen las dos\nconsole.log(edad < 18 || tieneEntrada);    // true: basta con una\nconsole.log(!tieneEntrada);                // false: invierte", "h": "Combina condiciones con y, o y no.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador lógico «y» es ___. (2 caracteres)", "e": "Usar & en lugar de &&."},
  {"m": "Variables, tipos y operadores", "t": "Plantillas de texto", "x": "Textos entre comillas invertidas que incluyen valores con ${}.\n\nCon comillas invertidas puedes escribir `Hola, ${nombre}` y JavaScript reemplaza ${nombre} por su valor. Dentro de ${} puedes poner cualquier expresión. Además, permiten escribir texto en varias líneas sin símbolos especiales.", "u": "Construir frases con variables de forma clara.\n\nQuieres construir la frase «Hola, Ana, tienes 20 años» insertando variables sin concatenar con +.", "p": ["Las plantillas de texto usan comillas invertidas.", "${expresión} inserta un valor dentro del texto.", "Permiten escribir texto de varias líneas."], "c": "const nombre = \"Ana\";\nconst edad = 20;\nconsole.log(`Hola, ${nombre}, tienes ${edad} años`);\nconsole.log(`El año que viene tendrás ${edad + 1}`);   // admite expresiones", "h": "Inserta variables y un cálculo dentro de una frase.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las plantillas de texto se escriben entre comillas ___. (9 letras: invertidas)", "e": "Usar comillas normales y esperar que ${} funcione."},
  {"m": "Variables, tipos y operadores", "t": "Conversión de tipos", "x": "Cambiar un dato de un tipo a otro.\n\nNumber(\"42\") convierte texto en número, String(42) convierte un número en texto y parseInt o parseFloat extraen números de textos. Los datos que llegan de formularios son siempre texto, así que hay que convertirlos antes de calcular.", "u": "Operar con números que llegan como texto.\n\nRecibes «42» como texto desde un formulario y necesitas sumarle 1.", "p": ["Number() convierte un texto en número.", "String() convierte un valor en texto.", "Los datos de un formulario llegan siempre como texto."], "c": "const texto = \"42\";\nconsole.log(texto + 1);              // \"421\" (concatena)\nconsole.log(Number(texto) + 1);      // 43 (suma de verdad)\nconsole.log(String(7) + \"!\");        // \"7!\"\nconsole.log(parseInt(\"15 años\"));    // 15", "h": "Compara concatenar con sumar tras convertir el texto a número.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que convierte un texto en número es ___(). (6 letras)", "e": "Sumar el valor de un formulario sin convertirlo a número."},
  {"m": "Variables, tipos y operadores", "t": "NaN", "x": "Valor especial que significa «no es un número».\n\nNaN aparece cuando una operación numérica no tiene sentido: Number(\"hola\") o 0/0. Curiosamente, typeof NaN es \"number\" y NaN no es igual ni a sí mismo. Para detectarlo usa Number.isNaN(valor).", "u": "Detectar cálculos con datos inválidos.\n\nUna conversión de «hola» a número da un resultado que significa «no es un número».", "p": ["NaN aparece cuando una operación numérica no es válida.", "NaN no es igual a sí mismo.", "Se detecta con Number.isNaN()."], "c": "const r = Number(\"hola\");\nconsole.log(r);                  // NaN\nconsole.log(r === NaN);          // false (NaN no es igual a nada)\nconsole.log(Number.isNaN(r));    // true  (la forma correcta de detectarlo)\nconsole.log(typeof NaN);         // number", "h": "Provoca un NaN y lo detecta con la comprobación correcta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función para detectar NaN es Number.is___(). (3 letras)", "e": "Comparar con === NaN para detectarlo."},
  {"m": "Variables, tipos y operadores", "t": "Objeto Math", "x": "Objeto con funciones y constantes matemáticas.\n\nMath.round redondea al entero más cercano, Math.floor hacia abajo y Math.ceil hacia arriba. Math.max y Math.min devuelven el mayor y menor. Math.random da un decimal aleatorio entre 0 y 1: multiplicado y redondeado sirve para dados o sorteos.", "u": "Redondear, elegir mínimos y máximos o generar azar.\n\nQuieres simular una tirada de dado de 1 a 6.", "p": ["Math.round redondea al entero más cercano.", "Math.random devuelve un número entre 0 y 1.", "Math.max devuelve el mayor de varios números."], "c": "console.log(Math.round(4.6), Math.floor(4.6), Math.ceil(4.2));   // 5 4 5\nconsole.log(Math.max(3, 9, 5), Math.min(3, 9, 5));                // 9 3\nconst dado = Math.floor(Math.random() * 6) + 1;                   // 1 a 6\nconsole.log(dado >= 1 && dado <= 6);", "h": "Redondea de tres maneras, busca máximos y mínimos y simula un dado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que devuelve un número aleatorio es Math.___(). (6 letras)", "e": "Olvidar que Math.random nunca llega a 1."},
  {"m": "Variables, tipos y operadores", "t": "Métodos de string", "x": "Funciones propias de los textos para transformarlos o buscar en ellos.\n\ntoUpperCase y toLowerCase cambian las letras; trim quita espacios sobrantes; includes comprueba si contiene un texto; replace sustituye; slice extrae un fragmento; split divide el texto en un array. Todos devuelven un resultado nuevo sin modificar el original.", "u": "Limpiar, buscar y cambiar textos.\n\nQuieres quitar los espacios sobrantes del principio y del final de lo que escribió el usuario.", "p": ["trim elimina los espacios del principio y del final.", "includes comprueba si un texto contiene otro.", "Los métodos de string no modifican el original."], "c": "const frase = \"  Aprendo JavaScript  \";\nconsole.log(frase.trim());                 // sin espacios en los extremos\nconsole.log(frase.includes(\"Java\"));       // true\nconsole.log(frase.replace(\"Aprendo\", \"Disfruto\").trim());\nconsole.log(\"a,b,c\".split(\",\"));           // [\"a\", \"b\", \"c\"]\nconsole.log(\"JavaScript\".slice(0, 4));     // Java", "h": "Limpia, busca, reemplaza, divide y recorta un texto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que quita espacios de los extremos es ___. (4 letras)", "e": "Creer que replace modifica el texto original."},
  {"m": "Variables, tipos y operadores", "t": "Truthy y falsy", "x": "Valores que se comportan como verdadero o falso en una condición.\n\nLos valores falsy son false, 0, \"\" (texto vacío), null, undefined y NaN. Todo lo demás es truthy, incluidos \"0\", [] y {}. Por eso if (nombre) es verdadero si hay un nombre escrito. Con !! conviertes cualquier valor a booleano.", "u": "Escribir condiciones más cortas.\n\nQuieres saber si una variable de texto contiene algo, sin escribir una comparación larga.", "p": ["0, texto vacío, null, undefined y NaN son falsy.", "Un array vacío es truthy.", "!! convierte cualquier valor en un booleano."], "c": "console.log(Boolean(0), Boolean(\"\"), Boolean(null));      // falsy: false false false\nconsole.log(Boolean(\"0\"), Boolean([]), Boolean({}));      // truthy: true true true\nconst nombre = \"\";\nif (!nombre) console.log(\"No escribiste tu nombre\");", "h": "Muestra qué valores se consideran falsos y cuáles verdaderos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor 0 se considera ___. (5 letras: falsy)", "e": "Pensar que un array vacío es falsy."},
  {"m": "Variables, tipos y operadores", "t": "Operador ternario", "x": "Forma corta de elegir entre dos valores según una condición.\n\nSe escribe condición ? valorSiVerdadero : valorSiFalso. Es perfecto para asignar un valor u mostrar un texto según una condición sencilla. Si la lógica se complica, es mejor un if normal.", "u": "Escribir un if simple en una sola línea.\n\nQuieres guardar «Adulto» o «Menor» según la edad escribiendo solo una línea.", "p": ["El operador ternario tiene la forma condición ? a : b.", "Devuelve un valor, no solo ejecuta código.", "Para lógica complicada es mejor un if normal."], "c": "const edad = 16;\nconst etiqueta = edad >= 18 ? \"Adulto\" : \"Menor\";\nconsole.log(etiqueta);                          // Menor\nconsole.log(`Tienes ${edad} años: ${edad >= 18 ? \"puedes votar\" : \"aún no votas\"}`);", "h": "Elige un texto según la edad con una expresión de una línea.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador ternario se escribe condición ? a ___ b. (un carácter)", "e": "Anidar muchos ternarios hasta que nadie lo entienda."},
  {"m": "Decisiones, bucles y funciones", "t": "if", "x": "Estructura que ejecuta código solo si una condición es verdadera.\n\nSe escribe if (condición) { ... }. Si la condición es true se ejecuta el bloque; si es false se salta. La condición va entre paréntesis y el código entre llaves. Aunque con una sola línea las llaves son opcionales, es mejor ponerlas siempre.", "u": "Tomar decisiones en el programa.\n\nQuieres mostrar un aviso solo cuando la edad sea 18 o más.", "p": ["if ejecuta un bloque solo si la condición es verdadera.", "La condición va entre paréntesis.", "El bloque de código va entre llaves."], "c": "const edad = 20;\nif (edad >= 18) {\n  console.log(\"Eres mayor de edad\");   // solo se ejecuta si la condición es true\n}\nconsole.log(\"Fin del programa\");       // esta línea se ejecuta siempre", "h": "Muestra un aviso solo si la edad es mayor o igual a 18.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La estructura que ejecuta código solo si algo es verdadero es ___. (2 letras)", "e": "Olvidar los paréntesis de la condición. La condición debe ir entre paréntesis: if (edad >= 18)."},
  {"m": "Decisiones, bucles y funciones", "t": "else", "x": "Rama que se ejecuta cuando la condición del if es falsa.\n\nelse va justo después del bloque del if y se ejecuta si la condición no se cumplió. Garantiza que siempre se ejecute exactamente una de las dos ramas. No lleva condición propia.", "u": "Elegir entre dos caminos.\n\nQuieres mostrar «Mayor» si la edad es 18 o más y «Menor» en caso contrario.", "p": ["else se ejecuta cuando el if no se cumple.", "else no lleva condición.", "Con if y else siempre se ejecuta exactamente una rama."], "c": "const edad = 15;\nif (edad >= 18) {\n  console.log(\"Mayor de edad\");\n} else {\n  console.log(\"Menor de edad\");   // se ejecuta porque 15 no es >= 18\n}", "h": "Elige entre dos mensajes según la edad.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La rama que se ejecuta cuando el if es falso es ___. (4 letras)", "e": "Escribir una condición después de else."},
  {"m": "Decisiones, bucles y funciones", "t": "else if", "x": "Rama intermedia que prueba otra condición.\n\nEncadena condiciones: if (a) {...} else if (b) {...} else {...}. JavaScript prueba cada una de arriba abajo y ejecuta solo la primera que sea verdadera. El orden importa: pon primero las condiciones más específicas.", "u": "Elegir entre más de dos caminos.\n\nQuieres asignar una letra según la nota: A, B o C.", "p": ["else if añade una condición intermedia.", "Se ejecuta solo la primera rama cuya condición sea verdadera.", "El orden de las condiciones importa."], "c": "const nota = 7;\nif (nota >= 9) {\n  console.log(\"A\");\n} else if (nota >= 7) {\n  console.log(\"B\");          // esta se ejecuta\n} else {\n  console.log(\"C\");\n}", "h": "Asigna una letra según la nota probando condiciones en orden.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La rama intermedia entre if y else se escribe else ___. (2 letras)", "e": "Poner las condiciones en un orden que nunca se cumple. La condición nota >= 9 nunca se alcanza: ya entró la primera. Hay que poner la más específica primero."},
  {"m": "Decisiones, bucles y funciones", "t": "switch", "x": "Estructura que compara un valor con varios casos.\n\nswitch (valor) { case 1: ...; break; default: ... }. Compara con === cada caso. break evita que continúe con el siguiente caso; default funciona como else. Ideal para días de la semana, opciones de menú o estados.", "u": "Elegir entre muchas opciones fijas de forma clara.\n\nQuieres mostrar el nombre del día según un número del 1 al 7.", "p": ["switch compara un valor con varios casos.", "break evita que se ejecuten los casos siguientes.", "default se ejecuta si ningún caso coincide."], "c": "const dia = 3;\nswitch (dia) {\n  case 1: console.log(\"Lunes\"); break;\n  case 2: console.log(\"Martes\"); break;\n  case 3: console.log(\"Miércoles\"); break;   // coincide\n  default: console.log(\"Otro día\");          // si nada coincide\n}", "h": "Muestra el nombre de un día según su número.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que evita seguir con los casos siguientes es ___. (5 letras)", "e": "Olvidar break y ejecutar casos de más."},
  {"m": "Decisiones, bucles y funciones", "t": "Bucle for", "x": "Bucle que repite código un número de veces conocido.\n\nfor (let i = 0; i < 5; i++) { ... } tiene tres partes: inicio (let i = 0), condición (i < 5) y avance (i++). Se repite mientras la condición sea true. Cuidado con empezar en 1 si quieres cinco vueltas desde 0.", "u": "Repetir tareas sin copiar el código.\n\nQuieres mostrar los números del 1 al 5, repitiendo la misma instrucción.", "p": ["El for tiene inicio, condición y avance.", "Se repite mientras la condición sea verdadera.", "i++ aumenta el contador en uno."], "c": "for (let i = 1; i <= 5; i++) {\n  console.log(\"Vuelta\", i);       // se repite 5 veces\n}\nconsole.log(\"Fin\");", "h": "Repite cinco vueltas numeradas con un bucle for.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bucle que repite un número conocido de veces es el ___. (3 letras)", "e": "Escribir una condición que nunca se vuelve falsa y crear un bucle infinito."},
  {"m": "Decisiones, bucles y funciones", "t": "Bucle while", "x": "Bucle que repite código mientras se cumpla una condición.\n\nwhile (condición) { ... } comprueba la condición antes de cada vuelta. Si la condición nunca cambia, el bucle es infinito, así que dentro debe modificarse algo que acabe haciéndola falsa. Es ideal para «repite hasta que ocurra algo».", "u": "Repetir cuando no se sabe cuántas veces.\n\nQuieres dividir un número entre 2 repetidamente mientras sea mayor que 1, sin saber cuántas veces.", "p": ["while repite mientras la condición sea verdadera.", "La condición se comprueba antes de cada vuelta.", "Dentro del bucle debe cambiar algo para que termine."], "c": "let n = 100;\nlet pasos = 0;\nwhile (n > 1) {          // se repite mientras n sea mayor que 1\n  n = n / 2;\n  pasos++;\n}\nconsole.log(\"Pasos:\", pasos);", "h": "Divide un número entre dos mientras sea mayor que uno y cuenta los pasos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bucle que repite mientras se cumpla una condición es ___. (5 letras)", "e": "Olvidar actualizar la variable de la condición."},
  {"m": "Decisiones, bucles y funciones", "t": "Bucle do while", "x": "Bucle que ejecuta el bloque al menos una vez.\n\ndo { ... } while (condición); ejecuta primero el bloque y luego comprueba la condición. Por eso siempre se ejecuta al menos una vez, a diferencia de while. Es útil para menús o para pedir un dato hasta que sea válido.", "u": "Repetir comprobando la condición al final.\n\nQuieres que un mensaje se muestre al menos una vez aunque la condición sea falsa desde el principio.", "p": ["do while ejecuta el bloque al menos una vez.", "La condición se comprueba después de cada vuelta.", "Termina con punto y coma tras el while."], "c": "let intentos = 5;\ndo {\n  console.log(\"Se ejecuta al menos una vez, intentos =\", intentos);\n  intentos++;\n} while (intentos < 3);    // la condición ya era falsa, pero el bloque corrió una vez", "h": "Ejecuta un bloque una vez aunque la condición sea falsa desde el inicio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bucle que ejecuta el bloque al menos una vez es do ___. (5 letras)", "e": "Creer que do while puede no ejecutarse nunca."},
  {"m": "Decisiones, bucles y funciones", "t": "break y continue", "x": "Instrucciones que cortan un bucle o saltan una vuelta.\n\nbreak termina el bucle completamente. continue salta el resto de la vuelta actual y pasa a la siguiente. Se usan con un if: «si encuentro lo que buscaba, break» o «si el número es par, continue».", "u": "Salir antes de tiempo o ignorar ciertos casos.\n\nQuieres dejar de recorrer una lista en cuanto encuentres el número 7.", "p": ["break termina el bucle por completo.", "continue salta solo la vuelta actual.", "Suelen usarse dentro de un if."], "c": "for (let i = 1; i <= 10; i++) {\n  if (i % 2 === 0) continue;     // salta los pares\n  if (i === 7) break;            // sale del bucle al llegar a 7\n  console.log(i);                // 1, 3, 5\n}", "h": "Salta números pares y se detiene al llegar al 7.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que termina un bucle es ___. (5 letras)", "e": "Usar break cuando se quería continue."},
  {"m": "Decisiones, bucles y funciones", "t": "Bucles anidados", "x": "Bucles escritos dentro de otros bucles.\n\nPor cada vuelta del bucle externo, el interno realiza todas sus vueltas. Un bucle de 3 vueltas con otro interno de 4 ejecuta el interior 12 veces. Se usan para tablas de multiplicar, matrices y dibujar figuras con texto.", "u": "Recorrer tablas, cuadrículas y combinaciones.\n\nQuieres imprimir una tabla de multiplicar completa recorriendo filas y columnas.", "p": ["El bucle interno completa todas sus vueltas por cada vuelta del externo.", "Dos bucles de 3 y 4 vueltas ejecutan el interior 12 veces.", "Sirven para recorrer tablas y cuadrículas."], "c": "for (let fila = 1; fila <= 3; fila++) {\n  let linea = \"\";\n  for (let col = 1; col <= 3; col++) {\n    linea += fila * col + \" \";          // el interno se repite por cada fila\n  }\n  console.log(linea);\n}", "h": "Construye una tabla de multiplicar 3 por 3 con dos bucles.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un bucle dentro de otro bucle se llama bucle ___. (8 letras)", "e": "Usar el mismo nombre de contador en los dos bucles."},
  {"m": "Decisiones, bucles y funciones", "t": "Funciones", "x": "Bloques de código con nombre que se ejecutan al llamarlos.\n\nfunction saludar() { ... } define la función y saludar() la ejecuta. Dar un nombre claro a cada función hace el programa más fácil de leer. Una función puede llamarse cuantas veces haga falta y desde cualquier punto donde sea visible.", "u": "Reutilizar código y dividir un programa en partes.\n\nQuieres agrupar tres líneas de código bajo un nombre para usarlas varias veces.", "p": ["Una función se define con la palabra function.", "Se ejecuta al llamarla con paréntesis.", "Un buen nombre de función describe lo que hace."], "c": "function mostrarBienvenida() {\n  console.log(\"¡Bienvenida!\");\n  console.log(\"Aprende a tu ritmo\");\n}\nmostrarBienvenida();     // llamada 1\nmostrarBienvenida();     // llamada 2", "h": "Define una función de bienvenida y la llama dos veces.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que define una función es ___. (8 letras)", "e": "Definir una función y olvidarse de llamarla. Falta llamar a la función con paréntesis: saludar()."},
  {"m": "Decisiones, bucles y funciones", "t": "Parámetros y argumentos", "x": "Datos que una función recibe para trabajar con ellos.\n\nLos parámetros son los nombres entre paréntesis al definir la función; los argumentos son los valores que pasas al llamarla. function saludar(nombre) recibe un valor distinto cada vez: saludar(\"Ana\"), saludar(\"Luis\"). El orden de los argumentos importa.", "u": "Hacer funciones flexibles que sirven para distintos valores.\n\nQuieres que una función salude a quien le indiques, no siempre a la misma persona.", "p": ["Los parámetros se escriben al definir la función.", "Los argumentos son los valores que se pasan al llamarla.", "El orden de los argumentos importa."], "c": "function saludar(nombre, ciudad) {      // nombre y ciudad: parámetros\n  console.log(`Hola, ${nombre} de ${ciudad}`);\n}\nsaludar(\"Ana\", \"Lima\");                  // \"Ana\" y \"Lima\": argumentos\nsaludar(\"Luis\", \"Bogotá\");", "h": "Saluda a distintas personas pasando valores distintos a la función.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los nombres entre paréntesis al definir una función son los ___. (10 letras)", "e": "Pasar los argumentos en distinto orden al esperado."},
  {"m": "Decisiones, bucles y funciones", "t": "return", "x": "Instrucción que devuelve un valor desde una función.\n\nreturn termina la función y entrega un valor a quien la llamó. Una función sin return devuelve undefined. console.log solo muestra algo en pantalla; return permite guardar el resultado en una variable. Lo que escribas después de return no se ejecuta.", "u": "Obtener el resultado de una función para usarlo después.\n\nQuieres que una función calcule un total y te lo entregue para guardarlo en una variable.", "p": ["return devuelve un valor y termina la función.", "Sin return, una función devuelve undefined.", "Lo escrito después de return no se ejecuta."], "c": "function sumar(a, b) {\n  return a + b;            // devuelve el resultado y termina\n  console.log(\"No se ejecuta\");\n}\nconst total = sumar(3, 4); // el resultado se guarda\nconsole.log(total);        // 7", "h": "Devuelve la suma de dos números y la guarda en una variable.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que devuelve un valor desde una función es ___. (6 letras)", "e": "Usar console.log en lugar de return y no poder guardar el resultado. Falta return: sin él la función devuelve undefined."},
  {"m": "Decisiones, bucles y funciones", "t": "Funciones flecha", "x": "Sintaxis corta para escribir funciones con =>.\n\nconst doble = (n) => n * 2; equivale a una función normal. Si solo hay una expresión, el return es implícito; con llaves, hay que escribir return. Con un único parámetro se pueden omitir los paréntesis. No tienen su propio this.", "u": "Escribir funciones breves, sobre todo como argumentos.\n\nQuieres escribir una función corta que devuelva el doble de un número en una sola línea.", "p": ["Las funciones flecha usan la sintaxis =>.", "Con una sola expresión, el return es implícito.", "Con llaves hay que escribir return explícitamente."], "c": "const doble = (n) => n * 2;            // return implícito\nconst sumar = (a, b) => {\n  const resultado = a + b;\n  return resultado;                    // con llaves, return explícito\n};\nconsole.log(doble(21), sumar(3, 4));", "h": "Define funciones con flecha, una de una línea y otra con llaves.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El símbolo de las funciones flecha es ___. (2 caracteres)", "e": "Usar llaves en una flecha y olvidar el return."},
  {"m": "Decisiones, bucles y funciones", "t": "Parámetros por defecto", "x": "Valores que usa un parámetro cuando no se le pasa argumento.\n\nfunction saludar(nombre = \"visitante\") usa «visitante» si llamas a saludar() sin argumento. Solo se aplica cuando el valor es undefined. Los parámetros con valor por defecto suelen ir al final.", "u": "Evitar errores cuando falta un dato opcional.\n\nQuieres que una función use «visitante» si no le dicen el nombre.", "p": ["Un parámetro por defecto se escribe con = y un valor.", "Solo se usa cuando falta el argumento.", "Suelen colocarse al final de la lista de parámetros."], "c": "function saludar(nombre = \"visitante\") {\n  console.log(`Hola, ${nombre}`);\n}\nsaludar(\"Ana\");      // Hola, Ana\nsaludar();           // Hola, visitante", "h": "Saluda con un nombre por defecto cuando no se indica ninguno.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un parámetro por defecto se escribe parámetro ___ valor. (un carácter)", "e": "Poner el parámetro por defecto antes de los obligatorios."},
  {"m": "Decisiones, bucles y funciones", "t": "Ámbito de variables", "x": "Zona del código donde una variable existe y se puede usar.\n\nUna variable declarada dentro de una función o de unas llaves solo existe ahí (ámbito local). Una declarada fuera es global y la ven todas las funciones. Evita las globales: pueden modificarse desde cualquier parte y provocar errores difíciles de rastrear.", "u": "Saber dónde se puede leer cada variable.\n\nUna variable creada dentro de una función no se puede leer desde fuera.", "p": ["Una variable local solo existe dentro de su bloque o función.", "Una variable global se ve en todo el programa.", "Conviene evitar las variables globales."], "c": "const global = \"visible en todas partes\";\nfunction prueba() {\n  const local = \"solo existe aquí\";\n  console.log(global, local);\n}\nprueba();\nconsole.log(typeof local);     // undefined: local no existe fuera de la función", "h": "Compara una variable global con otra local que no existe fuera de su función.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una variable que solo existe dentro de una función es ___. (5 letras)", "e": "Intentar usar fuera de una función una variable local."},
  {"m": "Decisiones, bucles y funciones", "t": "Callbacks", "x": "Funciones que se pasan como argumento a otra función.\n\nEn JavaScript las funciones son valores: se pueden guardar en variables y pasar a otras funciones. La función que recibe a la otra la «llama de vuelta» (callback) cuando toca. Es la base de los eventos, los temporizadores y los métodos de arrays.", "u": "Decidir qué hacer cuando otra función termina o encuentra algo.\n\nQuieres decirle a una función qué hacer cuando acabe su tarea, pasándole otra función.", "p": ["Un callback es una función que se pasa como argumento.", "Las funciones son valores en JavaScript.", "Los eventos y temporizadores usan callbacks."], "c": "function procesar(numero, alTerminar) {\n  const resultado = numero * 2;\n  alTerminar(resultado);                    // llama de vuelta\n}\nprocesar(21, (r) => console.log(\"Resultado:\", r));   // el callback es la flecha", "h": "Pasa una función como argumento para que se ejecute al terminar el cálculo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una función que se pasa como argumento a otra se llama ___. (8 letras)", "e": "Llamar al callback con paréntesis en lugar de pasarlo."},
  {"m": "Decisiones, bucles y funciones", "t": "Recursividad", "x": "Técnica en la que una función se llama a sí misma.\n\nUna función recursiva necesita un caso base (cuándo parar) y un caso recursivo (cómo acercarse al caso base). El factorial de 5 es 5 por el factorial de 4, y así hasta 1. Sin caso base, la función se llama sin fin y da error de pila.", "u": "Resolver problemas que se repiten de forma similar.\n\nQuieres calcular el factorial de un número usando una función que se llama a sí misma.", "p": ["Una función recursiva se llama a sí misma.", "Necesita un caso base para detenerse.", "Sin caso base provoca un desbordamiento de pila."], "c": "function factorial(n) {\n  if (n <= 1) return 1;            // caso base: aquí se detiene\n  return n * factorial(n - 1);     // caso recursivo: se acerca al caso base\n}\nconsole.log(factorial(5));         // 120", "h": "Calcula un factorial con una función que se llama a sí misma.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La condición que detiene una función recursiva es el caso ___. (4 letras)", "e": "Olvidar el caso base y provocar un bucle infinito."},
  {"m": "Decisiones, bucles y funciones", "t": "Funciones anónimas", "x": "Funciones sin nombre usadas en el mismo lugar donde se escriben.\n\nfunction () { ... } o () => ... sin nombre propio. Se usan como callbacks: setTimeout(() => console.log(\"hola\"), 1000). Si la necesitas en varios sitios, dale un nombre. Un nombre también ayuda a leer los mensajes de error.", "u": "Definir una acción breve directamente donde se necesita.\n\nNecesitas una función muy corta que solo vas a usar una vez, justo donde la escribes.", "p": ["Una función anónima no tiene nombre.", "Se usan mucho como callbacks.", "Si se reutiliza, conviene darle un nombre."], "c": "const numeros = [1, 2, 3];\nconst dobles = numeros.map(function (n) {   // función anónima clásica\n  return n * 2;\n});\nconst triples = numeros.map((n) => n * 3);  // anónima con flecha\nconsole.log(dobles, triples);", "h": "Usa dos funciones sin nombre para transformar una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una función sin nombre se llama ___. (8 letras: anónima)", "e": "Repetir la misma función anónima en varios sitios."},
  {"m": "Decisiones, bucles y funciones", "t": "Funciones de orden superior", "x": "Funciones que reciben o devuelven otras funciones.\n\nmap, filter y reduce son de orden superior porque reciben una función. También lo es una función que devuelve otra: function multiplicador(n) { return (x) => x * n; }. Permiten componer comportamientos como piezas de construcción.", "u": "Crear herramientas reutilizables y flexibles.\n\nQuieres crear una función que fabrique otras funciones multiplicadoras.", "p": ["Una función de orden superior recibe o devuelve funciones.", "map, filter y reduce son funciones de orden superior.", "Permiten componer comportamientos reutilizables."], "c": "function multiplicador(n) {\n  return (x) => x * n;            // devuelve otra función\n}\nconst doble = multiplicador(2);\nconst triple = multiplicador(3);\nconsole.log(doble(5), triple(5));   // 10 15", "h": "Crea funciones multiplicadoras a partir de una función que devuelve funciones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una función que recibe o devuelve funciones es de orden ___. (8 letras: superior)", "e": "Olvidar que la función devuelta guarda el valor de n."},
  {"m": "Decisiones, bucles y funciones", "t": "Depurar con console", "x": "Técnicas para encontrar errores usando la consola.\n\nconsole.log muestra valores en el momento; console.table muestra arrays y objetos como tabla; console.error y console.warn resaltan problemas. Rastrea el programa «imprimiendo» los valores clave y comparando lo esperado con lo real.", "u": "Descubrir por qué un programa no hace lo esperado.\n\nUn cálculo da un resultado distinto al esperado y quieres inspeccionar los valores intermedios.", "p": ["console.log permite comprobar valores durante la ejecución.", "console.table muestra arrays y objetos como tabla.", "Comparar lo esperado con lo real localiza el error."], "c": "function promedio(a, b, c) {\n  console.log(\"Entradas:\", a, b, c);       // ¿llegan bien los datos?\n  const suma = a + b + c;\n  console.log(\"Suma:\", suma);              // ¿es la suma esperada?\n  return suma / 3;\n}\nconsole.log(\"Resultado:\", promedio(6, 8, 10));\nconsole.table([{ nombre: \"Ana\", nota: 9 }, { nombre: \"Luis\", nota: 7 }]);", "h": "Imprime valores intermedios y una tabla para depurar un cálculo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que muestra arrays y objetos como tabla es console.___. (5 letras)", "e": "Cambiar código al azar sin inspeccionar los valores."},
  {"m": "Arrays y objetos", "t": "Arrays", "x": "Lista ordenada de valores guardados en una sola variable.\n\nSe escriben entre corchetes y separados por comas: [\"Ana\", \"Luis\"]. Cada elemento tiene una posición (índice) que empieza en 0. La propiedad length da cuántos elementos hay. Un array puede mezclar tipos, aunque lo habitual es que todos sean del mismo.", "u": "Manejar muchos datos relacionados a la vez.\n\nQuieres guardar cinco nombres de alumnos en una sola variable.", "p": ["Un array se escribe entre corchetes.", "Los índices de un array empiezan en 0.", "La propiedad length indica cuántos elementos tiene."], "c": "const alumnos = [\"Ana\", \"Luis\", \"Marta\"];\nconsole.log(alumnos[0]);         // Ana (el primero es el 0)\nconsole.log(alumnos.length);     // 3\nconsole.log(alumnos[alumnos.length - 1]);   // Marta (el último)", "h": "Muestra el primer elemento, la cantidad y el último de una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un array se escribe entre ___. (corchetes)", "e": "Pedir el elemento en la posición length en lugar de length - 1."},
  {"m": "Arrays y objetos", "t": "Añadir y quitar elementos", "x": "Métodos que modifican los extremos de un array.\n\npush añade al final y pop quita el último. unshift añade al principio y shift quita el primero. Todos modifican el array original. push y unshift devuelven la nueva longitud; pop y shift devuelven el elemento quitado.", "u": "Agregar o eliminar elementos de una lista.\n\nQuieres añadir un nombre al final de una lista ya creada.", "p": ["push añade un elemento al final.", "pop quita y devuelve el último elemento.", "unshift añade al principio y shift quita el primero."], "c": "const cola = [\"Ana\", \"Luis\"];\ncola.push(\"Marta\");               // final: Ana, Luis, Marta\ncola.unshift(\"Pablo\");            // principio: Pablo, Ana, Luis, Marta\nconst salio = cola.shift();       // quita y devuelve el primero\ncola.pop();                       // quita el último\nconsole.log(salio, cola);", "h": "Añade y quita elementos por los dos extremos de una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que añade un elemento al final es ___. (4 letras)", "e": "Confundir pop (final) con shift (principio)."},
  {"m": "Arrays y objetos", "t": "Recorrer con for...of", "x": "Bucle que recorre los elementos de un array uno a uno.\n\nfor (const x of lista) { ... } da en cada vuelta un elemento. Es más claro que el for clásico cuando no necesitas la posición. Para tener el índice también usa lista.entries() o el for clásico.", "u": "Procesar cada elemento sin manejar índices.\n\nQuieres mostrar cada nombre de una lista sin preocuparte por los índices.", "p": ["for...of recorre cada elemento de un array.", "No hace falta manejar índices.", "Funciona con arrays, textos y otros iterables."], "c": "const frutas = [\"manzana\", \"pera\", \"uva\"];\nfor (const fruta of frutas) {       // fruta toma cada elemento\n  console.log(\"Me gusta la \" + fruta);\n}\nfor (const [i, fruta] of frutas.entries()) {   // con índice\n  console.log(i, fruta);\n}", "h": "Recorre una lista mostrando sus elementos, primero solos y luego con su índice.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para recorrer los elementos de un array se usa for...___. (2 letras)", "e": "Usar for...in con arrays y recibir los índices como texto."},
  {"m": "Arrays y objetos", "t": "forEach", "x": "Método que ejecuta una función por cada elemento del array.\n\nlista.forEach((elemento, indice) => { ... }) llama a la función una vez por elemento. No devuelve nada y no se puede detener con break. Para transformar datos se prefiere map, y para filtrar, filter.", "u": "Aplicar una acción a todos los elementos.\n\nQuieres ejecutar una acción para cada elemento de una lista sin crear otra lista.", "p": ["forEach ejecuta una función por cada elemento.", "forEach no devuelve un array nuevo.", "No se puede detener con break."], "c": "const notas = [7, 9, 5];\nnotas.forEach((nota, i) => {\n  console.log(`Examen ${i + 1}: ${nota}`);\n});\n// forEach no devuelve nada\nconsole.log(notas.forEach((n) => n));   // undefined", "h": "Muestra cada nota con su número de examen y comprueba que forEach no devuelve nada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que ejecuta una función por elemento es ___. (7 letras)", "e": "Usar forEach esperando un array nuevo con resultados."},
  {"m": "Arrays y objetos", "t": "map", "x": "Método que transforma cada elemento y devuelve un array nuevo.\n\nlista.map((x) => x * 2) crea un array nuevo con el resultado de aplicar la función a cada elemento. No modifica el original. Se usa para pasar de precios a precios con IVA o de objetos a sus nombres.", "u": "Convertir una lista en otra del mismo tamaño.\n\nQuieres obtener una lista con el doble de cada número de otra lista, sin modificarla.", "p": ["map devuelve un array nuevo del mismo tamaño.", "map no modifica el array original.", "Cada elemento se transforma con la función dada."], "c": "const numeros = [1, 2, 3, 4];\nconst dobles = numeros.map((n) => n * 2);\nconsole.log(dobles);        // [2, 4, 6, 8]\nconsole.log(numeros);       // [1, 2, 3, 4] sigue igual\nconst nombres = [{ nombre: \"Ana\" }, { nombre: \"Luis\" }].map((p) => p.nombre);\nconsole.log(nombres);", "h": "Duplica los números de una lista y extrae nombres de una lista de objetos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que transforma cada elemento en uno nuevo es ___. (3 letras)", "e": "Olvidar el return en map con llaves."},
  {"m": "Arrays y objetos", "t": "filter", "x": "Método que devuelve un array con los elementos que cumplen una condición.\n\nlista.filter((x) => x > 5) devuelve un array nuevo con los elementos para los que la función devolvió true. El array resultante puede tener menos elementos que el original. No modifica la lista inicial.", "u": "Quedarse solo con ciertos elementos.\n\nQuieres quedarte solo con las notas aprobadas de una lista.", "p": ["filter devuelve los elementos que cumplen la condición.", "El array resultante puede ser más corto.", "filter no modifica el array original."], "c": "const notas = [4, 7, 9, 3, 6];\nconst aprobadas = notas.filter((n) => n >= 5);\nconsole.log(aprobadas);       // [7, 9, 6]\nconsole.log(notas.length, aprobadas.length);   // 5 3", "h": "Se queda solo con las notas aprobadas de una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que conserva solo los elementos que cumplen una condición es ___. (6 letras)", "e": "Usar map cuando se quería filtrar."},
  {"m": "Arrays y objetos", "t": "reduce", "x": "Método que combina todos los elementos en un único valor.\n\nlista.reduce((acumulado, actual) => acumulado + actual, 0) recorre la lista guardando un acumulador. El segundo argumento (0) es el valor inicial. Sirve para sumas, promedios, máximos o para construir un objeto.", "u": "Sumar, contar o acumular resultados.\n\nQuieres sumar todos los precios de un carrito en un solo número.", "p": ["reduce combina todos los elementos en un solo valor.", "Usa un acumulador y un valor inicial.", "Sirve para sumas y recuentos."], "c": "const precios = [10, 20, 5];\nconst total = precios.reduce((acumulado, precio) => acumulado + precio, 0);\nconsole.log(total);           // 35\nconst maximo = precios.reduce((m, p) => (p > m ? p : m), precios[0]);\nconsole.log(maximo);          // 20", "h": "Suma una lista de precios y encuentra el mayor con reduce.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que reduce una lista a un solo valor es ___. (6 letras)", "e": "Olvidar el valor inicial en listas vacías."},
  {"m": "Arrays y objetos", "t": "find e includes", "x": "Métodos que buscan un elemento dentro de un array.\n\nfind devuelve el primer elemento que cumpla la condición (o undefined). findIndex devuelve su posición (o -1). includes devuelve true o false según si el valor existe. indexOf devuelve la posición de un valor concreto.", "u": "Saber si algo existe y obtenerlo.\n\nQuieres comprobar si una lista de invitados contiene a «Ana».", "p": ["find devuelve el primer elemento que cumple la condición.", "includes devuelve true o false.", "findIndex devuelve -1 si no encuentra nada."], "c": "const invitados = [\"Ana\", \"Luis\", \"Marta\"];\nconsole.log(invitados.includes(\"Ana\"));                  // true\nconsole.log(invitados.indexOf(\"Marta\"));                 // 2\nconst usuarios = [{ id: 1, nombre: \"Ana\" }, { id: 2, nombre: \"Luis\" }];\nconsole.log(usuarios.find((u) => u.id === 2));           // { id: 2, nombre: 'Luis' }\nconsole.log(usuarios.findIndex((u) => u.id === 99));     // -1", "h": "Busca un valor, una posición y un objeto dentro de listas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que devuelve true o false según si existe un valor es ___. (8 letras)", "e": "Usar == para comparar objetos dentro de includes."},
  {"m": "Arrays y objetos", "t": "sort", "x": "Método que ordena los elementos de un array.\n\nsort ordena el array original. Atención: por defecto ordena como texto, así que [10, 9, 1] queda [1, 10, 9]. Para números hay que pasar una función: sort((a, b) => a - b) para ascendente. Para copiar antes de ordenar, usa [...lista].sort().", "u": "Mostrar listas de menor a mayor o por texto.\n\nQuieres ordenar números de menor a mayor correctamente.", "p": ["sort modifica el array original.", "Por defecto, sort ordena como si fueran textos.", "Para ordenar números hay que usar (a, b) => a - b."], "c": "const numeros = [10, 9, 1, 100];\nconsole.log([...numeros].sort());                 // [1, 10, 100, 9] ¡como texto!\nconsole.log([...numeros].sort((a, b) => a - b));  // [1, 9, 10, 100]\nconsole.log([...numeros].sort((a, b) => b - a));  // de mayor a menor", "h": "Compara el orden de texto con el orden numérico correcto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para ordenar números de menor a mayor se usa sort((a, b) => a ___ b). (un carácter)", "e": "Ordenar números sin pasar una función de comparación."},
  {"m": "Arrays y objetos", "t": "slice y splice", "x": "Métodos para extraer o modificar una parte del array.\n\nslice(inicio, fin) devuelve una copia de un fragmento sin modificar el array (el fin no se incluye). splice(inicio, cuantos, ...nuevos) sí modifica el original: borra y/o inserta elementos. Se confunden con frecuencia: slice copia y splice cambia.", "u": "Copiar fragmentos o insertar y eliminar en el medio.\n\nQuieres copiar solo los tres primeros elementos de una lista sin tocarla.", "p": ["slice devuelve un fragmento sin modificar el original.", "splice modifica el array original.", "En slice, el índice final no se incluye."], "c": "const letras = [\"a\", \"b\", \"c\", \"d\", \"e\"];\nconsole.log(letras.slice(0, 3));       // [\"a\", \"b\", \"c\"]; letras no cambia\nconst copia = [...letras];\ncopia.splice(1, 2);                    // borra 2 elementos desde la posición 1\nconsole.log(copia);                    // [\"a\", \"d\", \"e\"]\ncopia.splice(1, 0, \"X\");               // inserta sin borrar\nconsole.log(copia);", "h": "Copia un fragmento de una lista y modifica otra insertando y borrando.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que copia un fragmento sin modificar es ___. (5 letras)", "e": "Usar splice creyendo que no modifica el array."},
  {"m": "Arrays y objetos", "t": "Spread y rest", "x": "Operador ... que expande o agrupa elementos.\n\n[...a, ...b] une dos arrays en uno nuevo y {...obj} copia un objeto. En la definición de una función, function sumar(...numeros) recoge todos los argumentos en un array (rest). Es una copia superficial: los objetos internos se comparten.", "u": "Copiar arrays, unirlos y recibir argumentos variables.\n\nQuieres unir dos arrays en uno nuevo sin modificar los originales.", "p": ["Spread expande los elementos de un array u objeto.", "Rest agrupa los argumentos sobrantes en un array.", "La copia con spread es superficial."], "c": "const a = [1, 2], b = [3, 4];\nconsole.log([...a, ...b, 5]);              // [1, 2, 3, 4, 5]\nconst persona = { nombre: \"Ana\", edad: 20 };\nconsole.log({ ...persona, edad: 21 });     // copia y cambia un valor\nfunction sumar(...numeros) {               // rest: recoge todos los argumentos\n  return numeros.reduce((s, n) => s + n, 0);\n}\nconsole.log(sumar(1, 2, 3, 4));", "h": "Une arrays, copia un objeto cambiando un valor y suma argumentos variables.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que expande elementos se escribe con ___ puntos. (un número)", "e": "Creer que el spread copia también los objetos internos."},
  {"m": "Arrays y objetos", "t": "Objetos", "x": "Colección de pares clave-valor que describe una cosa.\n\nSe escriben entre llaves: { nombre: \"Ana\", edad: 20 }. Cada propiedad tiene un nombre (clave) y un valor. Se accede con punto (persona.nombre) o con corchetes (persona[\"nombre\"]). Un objeto puede contener cualquier tipo, incluso otros objetos o funciones.", "u": "Agrupar datos relacionados de una misma entidad.\n\nQuieres guardar nombre, edad y ciudad de una persona en una sola variable.", "p": ["Un objeto se escribe entre llaves con pares clave-valor.", "Se accede a una propiedad con punto o con corchetes.", "Un objeto puede contener otros objetos."], "c": "const persona = {\n  nombre: \"Ana\",\n  edad: 20,\n  ciudad: \"Lima\",\n};\nconsole.log(persona.nombre);             // con punto\nconsole.log(persona[\"ciudad\"]);          // con corchetes\npersona.edad = 21;                       // modificar\npersona.correo = \"ana@correo.com\";       // añadir\nconsole.log(persona);", "h": "Crea un objeto persona y lee, cambia y añade propiedades.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un objeto se escribe entre ___. (llaves)", "e": "Olvidar la coma entre propiedades."},
  {"m": "Arrays y objetos", "t": "Métodos de objetos", "x": "Funciones guardadas como propiedades de un objeto.\n\nUn método es una función dentro de un objeto: { saludar() { ... } }. Dentro, this se refiere al propio objeto, así que this.nombre lee su propiedad. Cuidado: las funciones flecha no tienen this propio y no sirven como métodos.", "u": "Darle acciones a los datos del objeto.\n\nQuieres que un objeto persona tenga una acción para presentarse usando sus propios datos.", "p": ["Un método es una función guardada en un objeto.", "Dentro de un método, this apunta al objeto.", "Las funciones flecha no son buenas como métodos."], "c": "const persona = {\n  nombre: \"Ana\",\n  presentarse() {\n    return `Hola, soy ${this.nombre}`;    // this = el propio objeto\n  },\n};\nconsole.log(persona.presentarse());", "h": "Define un método que usa this para leer los datos de su objeto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Dentro de un método, la palabra que se refiere al propio objeto es ___. (4 letras)", "e": "Usar una función flecha como método y perder this."},
  {"m": "Arrays y objetos", "t": "Desestructuración", "x": "Forma corta de extraer valores de arrays u objetos.\n\nconst { nombre, edad } = persona crea las variables nombre y edad con los valores de esas propiedades. Con arrays, const [a, b] = lista toma por posición. Se pueden dar valores por defecto y renombrar: { nombre: n = \"sin nombre\" }.", "u": "Sacar varias propiedades a variables en una línea.\n\nQuieres sacar nombre y edad de un objeto a dos variables en una sola línea.", "p": ["La desestructuración extrae valores en variables.", "Con objetos se usan llaves y con arrays corchetes.", "Se pueden dar valores por defecto."], "c": "const persona = { nombre: \"Ana\", edad: 20, ciudad: \"Lima\" };\nconst { nombre, edad } = persona;            // objeto: por nombre\nconsole.log(nombre, edad);\nconst [primero, segundo] = [\"rojo\", \"verde\", \"azul\"];   // array: por posición\nconsole.log(primero, segundo);\nconst { pais = \"sin país\" } = persona;       // valor por defecto\nconsole.log(pais);", "h": "Extrae propiedades de un objeto y elementos de un array en variables.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Con objetos, la desestructuración usa ___. (llaves)", "e": "Usar corchetes al desestructurar un objeto."},
  {"m": "Arrays y objetos", "t": "Object.keys y entries", "x": "Funciones que obtienen las claves y valores de un objeto.\n\nObject.keys(obj) devuelve un array con las claves, Object.values(obj) con los valores y Object.entries(obj) con pares [clave, valor]. Combinadas con for...of o forEach permiten recorrer cualquier objeto.", "u": "Recorrer las propiedades de un objeto.\n\nQuieres recorrer todas las propiedades de un objeto para mostrarlas.", "p": ["Object.keys devuelve un array con las claves.", "Object.values devuelve un array con los valores.", "Object.entries devuelve pares clave-valor."], "c": "const precios = { pan: 1.2, leche: 0.9, huevos: 2.5 };\nconsole.log(Object.keys(precios));      // [\"pan\", \"leche\", \"huevos\"]\nconsole.log(Object.values(precios));    // [1.2, 0.9, 2.5]\nfor (const [producto, precio] of Object.entries(precios)) {\n  console.log(`${producto}: ${precio}`);\n}", "h": "Obtiene claves y valores de un objeto y los recorre en pares.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que devuelve las claves de un objeto es Object.___(). (4 letras)", "e": "Intentar recorrer un objeto con for...of sin entries."},
  {"m": "Arrays y objetos", "t": "Encadenamiento opcional", "x": "Operador ?. que evita errores al leer propiedades inexistentes.\n\npersona.direccion.calle falla si direccion es undefined. Con persona.direccion?.calle se devuelve undefined en lugar de error. El operador ?? da un valor por defecto solo cuando el resultado es null o undefined: persona.direccion?.calle ?? \"sin calle\".", "u": "Acceder a datos anidados que pueden no existir.\n\nQuieres leer la calle de una dirección que puede no existir sin que el programa falle.", "p": ["?. devuelve undefined si la propiedad intermedia no existe.", "?? da un valor por defecto si el resultado es null o undefined.", "Evita errores al leer datos anidados."], "c": "const persona = { nombre: \"Ana\" };          // no tiene dirección\n// console.log(persona.direccion.calle);       // ¡daría error!\nconsole.log(persona.direccion?.calle);         // undefined, sin error\nconsole.log(persona.direccion?.calle ?? \"sin calle\");   // valor por defecto", "h": "Lee una propiedad anidada que no existe sin provocar un error.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador de encadenamiento opcional se escribe ___. (2 caracteres)", "e": "Leer propiedades anidadas sin comprobar si existen."},
  {"m": "Arrays y objetos", "t": "Arrays de objetos", "x": "Listas donde cada elemento es un objeto.\n\nEs la estructura de datos más habitual en las aplicaciones: [{ id: 1, nombre: \"Ana\" }, { id: 2, nombre: \"Luis\" }]. Se combinan map, filter, find y sort para consultarla, como si fuera una base de datos pequeña.", "u": "Representar tablas de datos como usuarios o productos.\n\nQuieres guardar varios alumnos, cada uno con nombre y nota, y consultarlos.", "p": ["Un array de objetos representa una tabla de datos.", "Se consulta con map, filter, find y sort.", "Es la estructura de datos más habitual en las aplicaciones."], "c": "const alumnos = [\n  { nombre: \"Ana\", nota: 9 },\n  { nombre: \"Luis\", nota: 5 },\n  { nombre: \"Marta\", nota: 8 },\n];\nconst aprobados = alumnos.filter((a) => a.nota >= 6).map((a) => a.nombre);\nconsole.log(aprobados);                                      // [\"Ana\", \"Marta\"]\nconsole.log(alumnos.find((a) => a.nombre === \"Luis\").nota);  // 5", "h": "Filtra y consulta una lista de alumnos con nombre y nota.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una lista de objetos es un array de ___. (8 letras)", "e": "Olvidar la propiedad al leer un valor del objeto."},
  {"m": "Arrays y objetos", "t": "JSON", "x": "Formato de texto para guardar e intercambiar datos.\n\nJSON parece un objeto de JavaScript, pero es texto: las claves van entre comillas dobles y no admite funciones ni comentarios. JSON.stringify(objeto) lo convierte en texto y JSON.parse(texto) vuelve a convertirlo en objeto. Es el formato estándar de las API.", "u": "Enviar datos entre programas y guardarlos.\n\nQuieres convertir un objeto en texto para guardarlo o enviarlo por internet.", "p": ["JSON es un formato de texto para intercambiar datos.", "JSON.stringify convierte un objeto en texto.", "JSON.parse convierte un texto JSON en objeto."], "c": "const persona = { nombre: \"Ana\", edad: 20 };\nconst texto = JSON.stringify(persona);      // objeto -> texto\nconsole.log(texto);                         // {\"nombre\":\"Ana\",\"edad\":20}\nconst vuelta = JSON.parse(texto);           // texto -> objeto\nconsole.log(vuelta.nombre);\nconsole.log(typeof texto, typeof vuelta);", "h": "Convierte un objeto en texto JSON y lo recupera.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que convierte un objeto en texto JSON es JSON.___(). (9 letras)", "e": "Usar comillas simples en un JSON y recibir un error. JSON exige comillas dobles en claves y textos: {\"nombre\": \"Ana\"}."},
  {"m": "Arrays y objetos", "t": "Copiar y comparar", "x": "Diferencia entre copiar un valor y copiar una referencia.\n\nLos números y textos se copian por valor. Los objetos y arrays se guardan por referencia: b = a no crea una copia, ambas variables apuntan al mismo objeto. Para copiar usa spread o structuredClone. Dos objetos distintos con el mismo contenido no son === entre sí.", "u": "Evitar cambios inesperados al copiar objetos y arrays.\n\nAl cambiar una copia de un array cambia también el original.", "p": ["Los objetos se asignan por referencia, no por valor.", "b = a no crea una copia independiente de un objeto.", "Dos objetos con el mismo contenido no son iguales con ===."], "c": "const a = [1, 2, 3];\nconst b = a;                  // NO es una copia: apunta al mismo array\nb.push(4);\nconsole.log(a);               // [1, 2, 3, 4]\nconst c = [...a];             // copia real\nc.push(5);\nconsole.log(a.length, c.length);\nconsole.log([1] === [1]);     // false", "h": "Muestra que asignar no copia y que spread sí crea una copia.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los objetos se asignan por ___. (10 letras: referencia)", "e": "Creer que b = a copia un array."},
  {"m": "Arrays y objetos", "t": "Set y Map", "x": "Colecciones modernas para valores únicos y pares clave-valor.\n\nUn Set guarda valores sin repetir: new Set([1, 1, 2]) tiene dos elementos. Un Map asocia claves de cualquier tipo con valores, y recuerda el orden de inserción. [...new Set(lista)] es el truco clásico para quitar duplicados.", "u": "Quitar duplicados y asociar claves de cualquier tipo.\n\nQuieres quitar los valores repetidos de una lista.", "p": ["Un Set no admite valores repetidos.", "Un Map asocia claves con valores de cualquier tipo.", "[...new Set(lista)] elimina duplicados."], "c": "const repetidos = [1, 2, 2, 3, 3, 3];\nconst unicos = [...new Set(repetidos)];      // sin duplicados\nconsole.log(unicos);                         // [1, 2, 3]\nconst edades = new Map();\nedades.set(\"Ana\", 20).set(\"Luis\", 25);\nconsole.log(edades.get(\"Ana\"), edades.size); // 20 2", "h": "Elimina duplicados con un Set y guarda pares en un Map.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La estructura que no admite valores repetidos es el ___. (3 letras)", "e": "Usar un array y comprobar duplicados a mano."},
  {"m": "Arrays y objetos", "t": "Proyecto: lista de compras", "x": "Programa que reúne arrays, objetos y funciones.\n\nPara cerrar este bloque, crea una lista de compras: un array de objetos con nombre, precio y cantidad; una función que añade productos, otra que calcula el total y otra que muestra el resumen. Usa map, filter y reduce.", "u": "Practicar lo aprendido en un caso completo.\n\nQuieres cerrar este bloque con un programa que gestione una lista de compras con totales.", "p": ["Un proyecto pequeño combina arrays, objetos y funciones.", "reduce sirve para calcular el total del carrito.", "Dividir en funciones hace el programa más claro."], "c": "const carrito = [];\nfunction agregar(nombre, precio, cantidad = 1) {\n  carrito.push({ nombre, precio, cantidad });\n}\nfunction total() {\n  return carrito.reduce((suma, p) => suma + p.precio * p.cantidad, 0);\n}\nagregar(\"Pan\", 1.2, 2);\nagregar(\"Leche\", 0.9);\nconsole.log(carrito.map((p) => `${p.nombre} x${p.cantidad}`));\nconsole.log(\"Total:\", total().toFixed(2));", "h": "Gestiona un carrito con funciones para añadir productos y calcular el total.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que suma los precios del carrito es ___. (6 letras)", "e": "Repetir el cálculo del total en varios sitios en lugar de usar una función."},
  {"m": "DOM, eventos y asincronía", "t": "querySelector", "x": "Método que busca un elemento de la página con un selector CSS.\n\ndocument.querySelector(\"#titulo\") devuelve el primer elemento que coincida con el selector CSS (o null si no existe). querySelectorAll devuelve todos. Guarda el resultado en una constante para usarlo varias veces.", "u": "Obtener elementos del DOM para leerlos o cambiarlos.\n\nQuieres obtener el elemento con id «titulo» para cambiarlo desde JavaScript.", "p": ["querySelector usa selectores CSS para buscar elementos.", "querySelector devuelve el primero que coincida.", "querySelectorAll devuelve todos los que coincidan."], "c": "document.body.innerHTML = '<h1 id=\"titulo\">Hola</h1><p class=\"aviso\">Uno</p><p class=\"aviso\">Dos</p>';\nconst titulo = document.querySelector(\"#titulo\");        // el primero que coincide\nconst avisos = document.querySelectorAll(\".aviso\");       // todos los que coinciden\nconsole.log(titulo.textContent, avisos.length);", "h": "Busca un título por su id y cuenta los párrafos con una clase.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que busca el primer elemento con un selector CSS es document.___(). (13 letras)", "e": "Olvidar el # o el punto en el selector."},
  {"m": "DOM, eventos y asincronía", "t": "textContent e innerHTML", "x": "Propiedades que leen o cambian el contenido de un elemento.\n\ntextContent trata todo como texto plano y es seguro. innerHTML interpreta el texto como HTML, lo que permite insertar etiquetas, pero si incluyes datos de un usuario puede permitir ataques (XSS). Usa textContent siempre que no necesites HTML.", "u": "Mostrar texto o HTML nuevo en la página.\n\nQuieres mostrar el nombre que escribió un usuario sin que se interprete como HTML.", "p": ["textContent muestra el contenido como texto plano.", "innerHTML interpreta el contenido como HTML.", "innerHTML con datos de usuarios puede ser peligroso."], "c": "document.body.innerHTML = '<p id=\"a\"></p><p id=\"b\"></p>';\nconst texto = \"<b>negrita</b>\";\ndocument.querySelector(\"#a\").textContent = texto;   // se ve literalmente: <b>negrita</b>\ndocument.querySelector(\"#b\").innerHTML = texto;     // se interpreta: negrita\nconsole.log(document.querySelector(\"#a\").textContent);\nconsole.log(document.querySelector(\"#b\").innerHTML);", "h": "Muestra el mismo texto como texto literal y como HTML interpretado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad segura para mostrar texto es ___. (11 letras)", "e": "Usar innerHTML con datos escritos por usuarios."},
  {"m": "DOM, eventos y asincronía", "t": "Atributos y estilos", "x": "Formas de cambiar atributos HTML y estilos desde JavaScript.\n\nelemento.setAttribute(\"href\", \"...\") y getAttribute leen o cambian atributos. elemento.style.color = \"red\" cambia estilos en línea, con propiedades en camelCase (backgroundColor, no background-color). Para cambios de estilo más grandes es mejor alternar clases CSS.", "u": "Modificar enlaces, imágenes y apariencia de forma dinámica.\n\nQuieres cambiar el color de fondo de un elemento desde el código.", "p": ["setAttribute cambia el atributo de un elemento.", "elemento.style cambia estilos en línea.", "Las propiedades de style se escriben en camelCase."], "c": "document.body.innerHTML = '<a id=\"enlace\" href=\"#\">Enlace</a>';\nconst enlace = document.querySelector(\"#enlace\");\nenlace.setAttribute(\"href\", \"https://ejemplo.com\");   // cambia un atributo\nenlace.style.backgroundColor = \"gold\";                // camelCase\nenlace.style.fontSize = \"24px\";\nconsole.log(enlace.getAttribute(\"href\"), enlace.style.backgroundColor);", "h": "Cambia un atributo y dos estilos de un enlace.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que cambia un atributo es ___(nombre, valor). (12 letras)", "e": "Escribir background-color con guion en style."},
  {"m": "DOM, eventos y asincronía", "t": "classList", "x": "Propiedad que añade, quita o alterna clases de un elemento.\n\nclassList.add(\"activo\") añade una clase, remove la quita, toggle la alterna (la añade si no está y la quita si está) y contains comprueba si la tiene. Es la forma recomendada de cambiar estilos: el CSS define el aspecto y JavaScript solo decide cuándo.", "u": "Cambiar el aspecto de un elemento con clases CSS.\n\nQuieres activar y desactivar el modo oscuro alternando una clase de un elemento.", "p": ["classList.add añade una clase.", "classList.toggle alterna una clase.", "Cambiar clases es mejor que cambiar estilos en línea."], "c": "document.body.innerHTML = '<div id=\"caja\">Hola</div>';\nconst caja = document.querySelector(\"#caja\");\ncaja.classList.add(\"activo\");\nconsole.log(caja.classList.contains(\"activo\"));   // true\ncaja.classList.toggle(\"activo\");                  // la quita porque estaba\nconsole.log(caja.classList.contains(\"activo\"));   // false", "h": "Añade, comprueba y alterna una clase de un elemento.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que añade o quita una clase según esté o no es classList.___(). (6 letras)", "e": "Escribir un punto delante del nombre de la clase en classList."},
  {"m": "DOM, eventos y asincronía", "t": "createElement y append", "x": "Métodos para crear elementos nuevos y añadirlos a la página.\n\ndocument.createElement(\"li\") crea el elemento en memoria. Después le pones contenido (textContent) y lo añades con padre.append(elemento). Hasta que lo añadas al DOM no se ve. Es más seguro que construir HTML con textos.", "u": "Generar contenido dinámico, como listas o tarjetas.\n\nQuieres añadir un nuevo elemento a una lista desde JavaScript.", "p": ["createElement crea un elemento nuevo.", "append añade un elemento dentro de otro.", "Un elemento no se ve hasta añadirlo al DOM."], "c": "document.body.innerHTML = '<ul id=\"lista\"></ul>';\nconst lista = document.querySelector(\"#lista\");\nfor (const nombre of [\"Ana\", \"Luis\", \"Marta\"]) {\n  const li = document.createElement(\"li\");   // se crea en memoria\n  li.textContent = nombre;                   // se le da contenido\n  lista.append(li);                          // se añade al DOM\n}\nconsole.log(lista.children.length);          // 3", "h": "Crea tres elementos de lista y los añade a la página.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que crea un elemento nuevo es document.___(). (13 letras)", "e": "Crear el elemento y olvidarse de añadirlo a la página."},
  {"m": "DOM, eventos y asincronía", "t": "Eliminar elementos", "x": "Métodos para quitar elementos del DOM.\n\nelemento.remove() elimina ese elemento de la página. Para vaciar un contenedor se usa contenedor.replaceChildren() o contenedor.textContent = \"\". Los elementos eliminados ya no se ven, pero la variable que los guardaba aún existe en memoria.", "u": "Borrar contenido que ya no se necesita.\n\nQuieres borrar de la página un elemento concreto.", "p": ["elemento.remove() elimina un elemento del DOM.", "replaceChildren() vacía un contenedor.", "Una variable puede seguir guardando un elemento ya eliminado."], "c": "document.body.innerHTML = '<ul id=\"l\"><li>Uno</li><li>Dos</li><li>Tres</li></ul>';\nconst lista = document.querySelector(\"#l\");\nlista.firstElementChild.remove();          // quita «Uno»\nconsole.log(lista.children.length);        // 2\nlista.replaceChildren();                   // vacía la lista\nconsole.log(lista.children.length);        // 0", "h": "Quita un elemento y luego vacía toda la lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que elimina un elemento del DOM es ___(). (6 letras)", "e": "Quitar el elemento de una variable creyendo que sale de la página."},
  {"m": "DOM, eventos y asincronía", "t": "addEventListener", "x": "Método que ejecuta una función cuando ocurre un evento.\n\nelemento.addEventListener(\"click\", funcion) registra la función como respuesta al evento. La función recibe un objeto evento con información. Puedes añadir varios oyentes al mismo evento. No escribas la llamada con paréntesis: pasas la función, no su resultado.", "u": "Reaccionar a lo que hace la persona en la página.\n\nQuieres ejecutar una función cuando se pulse un botón.", "p": ["addEventListener asocia una función a un evento.", "Se le pasa la función sin paréntesis.", "La función recibe un objeto con información del evento."], "c": "document.body.innerHTML = '<button id=\"b\">Pulsa</button>';\nconst boton = document.querySelector(\"#b\");\nlet veces = 0;\nboton.addEventListener(\"click\", () => {       // se pasa la función, sin ejecutarla\n  veces++;\n  console.log(\"Pulsado\", veces);\n});\nboton.click();          // simulamos dos pulsaciones\nboton.click();", "h": "Cuenta cuántas veces se pulsa un botón.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que asocia una función a un evento es ___EventListener. (3 letras: add)", "e": "Escribir boton.addEventListener(\"click\", funcion()) y ejecutarla al instante."},
  {"m": "DOM, eventos y asincronía", "t": "Eventos de teclado y entrada", "x": "Eventos que avisan al pulsar teclas o escribir en un campo.\n\nEl evento input se dispara cada vez que cambia el contenido de un campo; change, al salir de él. keydown y keyup avisan al pulsar y soltar teclas, y event.key dice cuál. En un campo, event.target.value da el texto actual.", "u": "Reaccionar mientras la persona escribe.\n\nQuieres mostrar cuántos caracteres lleva escritos una persona mientras escribe.", "p": ["El evento input se dispara cada vez que cambia el texto.", "event.key indica qué tecla se pulsó.", "event.target.value contiene el texto del campo."], "c": "document.body.innerHTML = '<input id=\"campo\"><p id=\"cuenta\"></p>';\nconst campo = document.querySelector(\"#campo\");\ncampo.addEventListener(\"input\", (evento) => {\n  document.querySelector(\"#cuenta\").textContent = evento.target.value.length;\n});\ncampo.value = \"Hola\";\ncampo.dispatchEvent(new Event(\"input\"));    // simulamos escribir\nconsole.log(document.querySelector(\"#cuenta\").textContent);   // 4", "h": "Muestra cuántos caracteres hay en un campo cada vez que cambia.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El evento que se dispara cada vez que cambia un campo es ___. (5 letras)", "e": "Leer el valor del campo antes de que ocurra el evento."},
  {"m": "DOM, eventos y asincronía", "t": "Formularios y preventDefault", "x": "Forma de controlar el envío de un formulario con JavaScript.\n\nEl evento submit se dispara al enviar el formulario. Por defecto recarga la página; evento.preventDefault() cancela ese comportamiento para que lo gestiones tú. Después lees los campos con evento.target.elements o con FormData.", "u": "Validar datos y evitar que la página se recargue.\n\nQuieres validar un formulario con JavaScript sin que la página se recargue al enviarlo.", "p": ["El evento submit se dispara al enviar un formulario.", "preventDefault cancela el comportamiento por defecto.", "FormData permite leer todos los campos del formulario."], "c": "document.body.innerHTML = '<form id=\"f\"><input name=\"nombre\" value=\"Ana\"><button>Enviar</button></form>';\nconst form = document.querySelector(\"#f\");\nform.addEventListener(\"submit\", (evento) => {\n  evento.preventDefault();                        // evita recargar la página\n  const datos = new FormData(form);\n  console.log(\"Nombre:\", datos.get(\"nombre\"));\n});\nform.dispatchEvent(new Event(\"submit\", { cancelable: true }));", "h": "Evita la recarga al enviar un formulario y lee el nombre escrito.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que cancela el comportamiento por defecto es ___(). (14 letras)", "e": "Olvidar preventDefault y ver cómo se recarga la página."},
  {"m": "DOM, eventos y asincronía", "t": "Delegación de eventos", "x": "Técnica de escuchar un evento en el padre para todos sus hijos.\n\nEn lugar de añadir un oyente a cada botón de una lista, lo añades al contenedor. El evento «burbujea» desde el hijo hacia el padre, y event.target indica en cuál se hizo clic. Funciona también con elementos añadidos más tarde.", "u": "Manejar muchos elementos, incluso los creados después, con un solo oyente.\n\nTienes una lista con muchos botones, algunos creados después, y quieres un solo oyente.", "p": ["La delegación usa un solo oyente en el elemento padre.", "event.target indica el elemento que originó el evento.", "Funciona también con elementos añadidos después."], "c": "document.body.innerHTML = '<ul id=\"l\"><li>Uno</li><li>Dos</li></ul>';\nconst lista = document.querySelector(\"#l\");\nlista.addEventListener(\"click\", (evento) => {       // un solo oyente en el padre\n  if (evento.target.tagName === \"LI\") console.log(\"Pulsaste:\", evento.target.textContent);\n});\nconst nuevo = document.createElement(\"li\");         // elemento creado después\nnuevo.textContent = \"Tres\";\nlista.append(nuevo);\nnuevo.click();                                      // también funciona", "h": "Usa un único oyente en la lista, incluso para un elemento añadido después.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En la delegación, el oyente se coloca en el elemento ___. (5 letras: padre)", "e": "Añadir un oyente a cada elemento de una lista enorme."},
  {"m": "DOM, eventos y asincronía", "t": "localStorage", "x": "Almacenamiento del navegador que guarda datos de forma permanente.\n\nlocalStorage.setItem(\"clave\", \"valor\") guarda un texto y getItem lo recupera, incluso tras cerrar el navegador. Solo guarda textos: para objetos usa JSON.stringify y JSON.parse. No es seguro para datos sensibles, porque cualquier script de la página puede leerlos.", "u": "Recordar preferencias y datos entre visitas.\n\nQuieres recordar el tema elegido por una persona la próxima vez que visite la página.", "p": ["localStorage guarda datos aunque se cierre el navegador.", "Solo almacena textos.", "No debe usarse para datos sensibles."], "c": "// En el navegador los datos sobreviven al cerrar la pestaña\nconst memoria = typeof localStorage !== \"undefined\" ? localStorage : new Map();\nconst guardar = (k, v) => (memoria.setItem ? memoria.setItem(k, v) : memoria.set(k, v));\nconst leer = (k) => (memoria.getItem ? memoria.getItem(k) : memoria.get(k));\nguardar(\"tema\", JSON.stringify({ oscuro: true }));        // objeto -> texto\nconsole.log(JSON.parse(leer(\"tema\")).oscuro);             // texto -> objeto", "h": "Guarda y recupera un objeto como texto JSON en el almacenamiento.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que guarda un dato en localStorage es ___Item. (3 letras: set)", "e": "Guardar objetos directamente sin convertirlos con JSON."},
  {"m": "DOM, eventos y asincronía", "t": "setTimeout y setInterval", "x": "Funciones que ejecutan código tras una espera o repetidamente.\n\nsetTimeout(funcion, 1000) ejecuta la función una vez tras 1000 milisegundos. setInterval la repite cada cierto tiempo hasta que la detengas con clearInterval. Ambas devuelven un identificador que se pasa a clearTimeout o clearInterval.", "u": "Retrasar acciones o repetirlas cada cierto tiempo.\n\nQuieres mostrar un mensaje a los dos segundos de abrir la página.", "p": ["setTimeout ejecuta una función una vez tras una espera.", "setInterval la repite cada cierto tiempo.", "clearInterval detiene un setInterval."], "c": "setTimeout(() => console.log(\"Pasó 1 segundo\"), 1000);   // una vez\nlet n = 0;\nconst id = setInterval(() => {\n  n++;\n  console.log(\"Tic\", n);\n  if (n === 3) clearInterval(id);                        // se detiene a los 3 tics\n}, 300);", "h": "Muestra un mensaje tras una espera y repite tres tics antes de detenerse.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que ejecuta algo una vez tras una espera es ___. (10 letras)", "e": "Olvidar clearInterval y dejar el temporizador funcionando siempre."},
  {"m": "DOM, eventos y asincronía", "t": "Promesas", "x": "Objeto que representa un resultado que llegará en el futuro.\n\nUna promesa puede estar pendiente, cumplida (resolve) o rechazada (reject). Con .then() se actúa cuando se cumple, con .catch() cuando falla y con .finally() siempre. Permite encadenar pasos y evita el «callback hell».", "u": "Manejar tareas lentas sin bloquear el programa.\n\nUna tarea tarda en terminar y quieres actuar cuando acabe, sin detener el resto del programa.", "p": ["Una promesa representa un resultado futuro.", ".then() se ejecuta cuando la promesa se cumple.", ".catch() se ejecuta cuando la promesa falla."], "c": "const esperar = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\nesperar(300)\n  .then(() => console.log(\"Cumplida\"))\n  .catch(() => console.log(\"Falló\"))\n  .finally(() => console.log(\"Fin (siempre)\"));\nconsole.log(\"Esto aparece primero\");", "h": "Crea una promesa que se cumple tras una espera y muestra los pasos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que actúa cuando una promesa se cumple es ___(). (4 letras)", "e": "Olvidar el catch y dejar los errores sin manejar."},
  {"m": "DOM, eventos y asincronía", "t": "async y await", "x": "Sintaxis para escribir código asíncrono como si fuera secuencial.\n\nUna función async siempre devuelve una promesa. Dentro, await pausa la función hasta que la promesa se cumple y entrega su valor. Hace que el código se lea de arriba abajo, sin cadenas de then. Solo se puede usar await dentro de una función async (o en módulos).", "u": "Esperar el resultado de una promesa de forma clara.\n\nQuieres esperar el resultado de una promesa escribiendo el código en orden, sin encadenar then.", "p": ["Una función async devuelve siempre una promesa.", "await espera a que una promesa se cumpla.", "await solo se usa dentro de funciones async."], "c": "const esperar = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\nasync function principal() {\n  console.log(\"Empiezo\");\n  await esperar(300);                   // pausa hasta que se cumpla\n  console.log(\"Pasaron 300 ms\");\n  return \"Terminé\";\n}\nprincipal().then(console.log);", "h": "Espera una promesa dentro de una función async y muestra los pasos en orden.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que espera a una promesa es ___. (5 letras)", "e": "Usar await fuera de una función async. await solo puede usarse dentro de una función declarada con async."},
  {"m": "DOM, eventos y asincronía", "t": "fetch", "x": "Función que pide datos a un servidor por internet.\n\nfetch(url) devuelve una promesa con la respuesta. Hay que convertirla con respuesta.json() (otra promesa) para leer el contenido. Comprueba respuesta.ok antes de usar los datos, porque fetch no falla ante un error 404 o 500, solo ante problemas de red.", "u": "Obtener información de una API.\n\nQuieres descargar datos de una API para mostrarlos en tu página.", "p": ["fetch pide datos a una dirección y devuelve una promesa.", "respuesta.json() convierte el cuerpo de la respuesta.", "fetch no rechaza la promesa con un error 404 o 500."], "c": "// Ejemplo ilustrativo: aquí simulamos la respuesta de una API\nconst fetchFalso = () => Promise.resolve({ ok: true, json: async () => ({ nombre: \"Ana\", edad: 20 }) });\nasync function cargar() {\n  const respuesta = await fetchFalso(\"https://api.ejemplo.com/usuario\");\n  if (!respuesta.ok) throw new Error(\"Respuesta incorrecta\");   // fetch real no falla con 404\n  const datos = await respuesta.json();\n  console.log(datos.nombre, datos.edad);\n}\ncargar();", "h": "Simula una petición a una API, comprueba la respuesta y lee sus datos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que pide datos por internet es ___(). (5 letras)", "e": "Usar los datos sin comprobar respuesta.ok."},
  {"m": "DOM, eventos y asincronía", "t": "try, catch y finally", "x": "Estructura para capturar errores y seguir ejecutando el programa.\n\nEl código que puede fallar va en try. Si ocurre un error, se salta a catch(error), donde puedes avisar y recuperarte. finally se ejecuta siempre, haya error o no. throw lanza un error propio. Con async/await, los errores de las promesas también se capturan con try/catch.", "u": "Evitar que un error detenga todo el programa.\n\nQuieres que el programa siga funcionando aunque una conversión de datos falle.", "p": ["try contiene el código que puede fallar.", "catch recibe el error y permite manejarlo.", "finally se ejecuta siempre."], "c": "function leerJSON(texto) {\n  try {\n    return JSON.parse(texto);               // puede fallar\n  } catch (error) {\n    console.log(\"Error:\", error.name);      // SyntaxError\n    return null;                            // nos recuperamos\n  } finally {\n    console.log(\"Intento terminado\");       // se ejecuta siempre\n  }\n}\nconsole.log(leerJSON('{\"a\": 1}'));\nconsole.log(leerJSON(\"esto no es JSON\"));", "h": "Captura un error de lectura de JSON y sigue funcionando.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bloque que se ejecuta siempre, haya error o no, es ___. (7 letras)", "e": "Dejar un catch vacío y esconder los errores."},
  {"m": "DOM, eventos y asincronía", "t": "Módulos import y export", "x": "Forma de dividir el código en archivos que comparten partes.\n\nCada archivo puede exportar funciones o valores con export, y otros los importan con import { sumar } from \"./matematicas.js\". En HTML se carga el archivo con <script type=\"module\">. Cada módulo tiene su propio ámbito, así que no hay choques de nombres.", "u": "Organizar proyectos grandes y evitar nombres repetidos.\n\nQuieres dividir tu código en varios archivos que se compartan funciones entre sí.", "p": ["export permite compartir algo desde un archivo.", "import trae lo exportado por otro archivo.", "Cada módulo tiene su propio ámbito."], "c": "// matematicas.js\n//   export function sumar(a, b) { return a + b; }\n//   export const PI = 3.1416;\n// app.js\n//   import { sumar, PI } from \"./matematicas.js\";\n// index.html\n//   <script type=\"module\" src=\"app.js\"></script>\nconst sumar = (a, b) => a + b;     // aquí lo escribimos directamente\nconsole.log(sumar(2, 3));", "h": "Muestra cómo exportar e importar funciones entre archivos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que comparte algo desde un archivo es ___. (6 letras)", "e": "Olvidar type=\"module\" al cargar el script."},
  {"m": "DOM, eventos y asincronía", "t": "Clases", "x": "Plantillas para crear objetos con los mismos datos y métodos.\n\nclass Persona { constructor(nombre) { this.nombre = nombre; } saludar() { ... } } define la plantilla. new Persona(\"Ana\") crea un objeto (instancia). El constructor inicializa los datos y los métodos se comparten. extends permite heredar de otra clase.", "u": "Crear muchos objetos parecidos de forma ordenada.\n\nQuieres crear muchos objetos persona con los mismos datos y métodos a partir de una plantilla.", "p": ["Una clase es una plantilla para crear objetos.", "El constructor inicializa los datos del objeto.", "new crea una instancia de la clase."], "c": "class Persona {\n  constructor(nombre, edad) {       // se ejecuta al crear el objeto\n    this.nombre = nombre;\n    this.edad = edad;\n  }\n  saludar() {\n    return `Hola, soy ${this.nombre} y tengo ${this.edad}`;\n  }\n}\nconst ana = new Persona(\"Ana\", 20);\nconst luis = new Persona(\"Luis\", 25);\nconsole.log(ana.saludar());\nconsole.log(luis.saludar());", "h": "Define una plantilla Persona y crea dos objetos a partir de ella.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que crea una instancia de una clase es ___. (3 letras)", "e": "Olvidar new al crear el objeto. Falta new: se debe crear con new Persona(\"Ana\")."},
  {"m": "DOM, eventos y asincronía", "t": "Burbujeo de eventos", "x": "Comportamiento por el que un evento sube del hijo a sus padres.\n\nCuando haces clic en un botón dentro de un div, el evento se dispara primero en el botón y luego «burbujea» hacia el div y hacia arriba hasta el documento. evento.stopPropagation() detiene ese ascenso. Es la base de la delegación de eventos.", "u": "Entender por qué se disparan oyentes de elementos contenedores.\n\nUn clic en un botón también activa el oyente del contenedor que lo rodea.", "p": ["Un evento sube desde el elemento hasta sus padres.", "stopPropagation detiene el ascenso del evento.", "El burbujeo hace posible la delegación de eventos."], "c": "document.body.innerHTML = '<div id=\"padre\"><button id=\"hijo\">Clic</button></div>';\ndocument.querySelector(\"#padre\").addEventListener(\"click\", () => console.log(\"Oyente del padre\"));\ndocument.querySelector(\"#hijo\").addEventListener(\"click\", () => console.log(\"Oyente del hijo\"));\ndocument.querySelector(\"#hijo\").click();      // se escribe primero el hijo y luego el padre", "h": "Muestra que un clic en el hijo también llega al padre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El comportamiento por el que un evento sube a los padres se llama ___. (9 letras: burbujeo)", "e": "Detener la propagación sin necesidad y romper otros oyentes."},
  {"m": "DOM, eventos y asincronía", "t": "Proyecto: lista de tareas", "x": "Aplicación web que reúne DOM, eventos y almacenamiento.\n\nPara cerrar JavaScript, crea una lista de tareas: un formulario para añadir tareas, una lista que se pinta con createElement, botones para marcarlas o borrarlas con delegación de eventos, y localStorage para guardarlas. Divide el código en funciones pequeñas.", "u": "Practicar todo lo aprendido en una aplicación real.\n\nQuieres cerrar el curso con una aplicación que permita añadir, completar y borrar tareas.", "p": ["Una lista de tareas combina DOM, eventos y almacenamiento.", "La delegación de eventos permite gestionar los botones de cada tarea.", "localStorage permite conservar las tareas entre visitas."], "c": "document.body.innerHTML = '<form id=\"f\"><input id=\"t\" value=\"Estudiar\"><button>Añadir</button></form><ul id=\"lista\"></ul>';\nconst tareas = [];\nconst lista = document.querySelector(\"#lista\");\nfunction pintar() {\n  lista.replaceChildren();\n  tareas.forEach((tarea, i) => {\n    const li = document.createElement(\"li\");\n    li.textContent = tarea;\n    li.dataset.indice = i;\n    lista.append(li);\n  });\n}\ndocument.querySelector(\"#f\").addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  tareas.push(document.querySelector(\"#t\").value);\n  pintar();\n});\ndocument.querySelector(\"#f\").dispatchEvent(new Event(\"submit\", { cancelable: true }));\nconsole.log(lista.children.length, tareas);", "h": "Añade una tarea desde un formulario y la pinta en una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para cerrar el curso conviene hacer un ___ completo. (8 letras)", "e": "Intentar escribir todo el programa de una sola vez sin dividirlo en funciones."}
];
